    "topic": "Türkiye'de Turizm / Turistik Rotalar ve Değerler",
    "questionText": "Bir seyahat acentesinin hazırlamış olduğu gezi planında aşağıdaki haritada konumu işaretlenmiş olan bir şelale, bir mağara, bir arkeolojik alan bir de farklı yer şekillerinin oluşturduğu doğal güzellik yer almaktadır.\n[Haritada Antalya kıyısından başlayarak sırasıyla Antalya doğusu (Manavgat), Alanya (Damlataş), Konya (Çatalhöyük) ve Nevşehir (Göreme Peri Bacaları) hattı işaretlenmiştir]\n\nYukarıda sözü edilen turistik mekânların sırası ile gezileceği bilindiğine göre bu mekânlar aşağıdakilerden hangisinde doğru verilmiş olabilir?",
    "options": {
      "A": "Manavgat Şelalesi, Damlataş Mağarası, Çatalhöyük, Göreme Peri Bacaları",
      "B": "Kurşunlu Şelalesi, İnsuyu Mağarası, Aşıklı Höyük, Ihlara Vadisi",
      "C": "Düden Şelalesi, Karain Mağarası, Alacahöyük, Pamukkale Travertenleri",
      "D": "Manavgat Şelalesi, Öküzini Mağarası, Çatalhöyük, Erciyes Dağı",
      "E": "Kurşunlu Şelalesi, Yarımburgaz Mağarası, Hacılar Höyüğü, Göreme Peri Bacaları"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Manavgat Şelalesi, Damlataş Mağarası, Çatalhöyük, Göreme Peri Bacaları\nHaritada gösterilen tur güzergahı sırasıyla şu durakları kapsar:\n1. Durak (Antalya - Manavgat): **Manavgat Şelalesi**\n2. Durak (Antalya - Alanya): **Damlataş Mağarası** (Türkiye'nin turizme açılan ilk mağarası - 1948)\n3. Durak (Konya - Çumra): **Çatalhöyük Neolitik Kenti** (UNESCO Dünya Mirası)\n4. Durak (Nevşehir): **Göreme Tarihî Milli Parkı ve Peri Bacaları** (Volkanik tüf ve bazalt aşınımı).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• İnsuyu Mağarası: Burdur'dadır.\n• Karain Mağarası: Antalya merkezin kuzeyindedir (Paleolitik ilk insan yerleşimi).\n• Alacahöyük: Çorum'dadır (İç Anadolu güzergahında değildir).\n• Pamukkale: Denizli'dedir (Ege bölgesindedir).\n• Ihlara Vadisi: Aksaray'dadır.\n\n💡 KPSS HAFIZA KARTI:\nUNESCO Miras Alanları:\n• Çatalhöyük (Konya) = İnsanlık tarihinin ilk toplu yerleşimi ve tarım kenti\n• Göreme ve Kapadokya (Nevşehir) = Hem doğal hem kültürel karma miras alanı.",
