    "explanation": "✅ DOĞRU CEVAP: C) Antalya - Isparta\nBir yerde karayolu ve demiryolu yapım maliyetinin yüksek olması; arazinin aşırı dağlık, engebeli olması, derin kanyon vadiler ve yüksek dağ sıraları içermesiyle ilgilidir. **Antalya ile Isparta arasında Batı Toroslar (Bey Dağları, Geyik Dağları) ve derin karstik boğazlar** uzandığı için köprü, viyadük, tünel ihtiyacı çok fazladır ve karayolu yapım maliyeti en yüksektir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Konya - Karaman: Geniş ova ve düzlüklerden oluşur; yol yapım maliyeti en düşüktür.\n• B) Şanlıurfa - Mardin: Güneydoğu plato düzlüğüdür; yol yapımı çok ucuzdur.\n• D) Edirne - Kırklareli: Ergene havzası düzlüğüdür; maliyet düşüktür.\n• E) Afyonkarahisar - Uşak: Ege'nin iç kesimi düzlükleridir; Toroslar kadar engebeli değildir.\n\n💡 KPSS HAFIZA KARTI:\nYol Yapım Maliyetinin EN YÜKSEK Olduğu Bölgeler:\n1. Doğu Karadeniz (Kaçkarlar)\n2. Akdeniz (Toros Dağ kuşağı)\n3. Doğu Anadolu (Hakkari Yöresi).\nEN DÜŞÜK Olduğu Bölgeler:\nİç Anadolu, Güneydoğu Anadolu, Marmara (Ergene).",
