    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Çay\nÇay bitkisi, taban arazilerdeki alüvyal kıyı ovalarında (delta ovalarında) yetişmez! Çayın yetişebilmesi için:\n1. Yıl boyunca kesintisiz nem ve bol yağış (en az 1600 mm),\n2. Kireçsiz, yıkanmış asitli topraklar,\n3. Suyun göllenmediği, drenajı iyi **EĞİMLİ DAĞ YAMAÇLARI** gerekir. Düz kıyı ovalarında su tabanda biriktiğinde çay kökleri çürür.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Soya Fasulyesi: Çukurova deltası ve kıyı ovalarında ikinci ürün olarak yaygın ekilir.\n• C) Pamuk: Çukurova, Gediz, Büyük Menderes gibi alüvyal kıyı ovalarının en büyük endüstri bitkisidir.\n• D) Mısır: Kıyı ovalarında sulama ile yüksek verim alınan temel üründür.\n• E) Tütün: Ege ovalarında (Bakırçay, Gediz) ve Samsun (Bafra, Çarşamba) deltalarında yetiştirilir.\n\n💡 KPSS HAFIZA KARTI:\nÇay Hakkında KPSS Özellikleri:\n• Türkiye üretiminin %100'ü Doğu Karadeniz'dedir (Rize lider, Trabzon, Artvin, Giresun).\n• Cumhuriyet döneminde Zihni Derin tarafından getirilmiştir.\n• Hasat edildikten hemen sonra işlenmek zorunda olduğu için fabrikaları tarım alanlarına en yakın olmak zorundadır.",
