    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Boksit\nÖncüllerdeki maden havzaları ve çıkarılan madenler:\n• Afşin-Elbistan (Kahramanmaraş) -> **Linyit** (B)\n• Kozlu-Karadon (Zonguldak) -> **Taş Kömürü** (C)\n• Fethiye-Köyceğiz (Muğla) -> **Krom** (D)\n• Mazıdağı (Mardin) -> **Fosfat** (E)\nBu eşleştirmelerde alüminyumun hammaddesi olan **BOKSİT madeni açıkta kalmaktadır!** Boksit madeninin en önemli yatakları **Konya-Seydişehir ve Antalya-Akseki**dedir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• Boksit (Alüminyum): Seydişehir fabrikasında işlenir (Hafif ve dayanıklı metal).\n• Linyit: III. Zaman tortulu olup Türkiye'nin hemen her bölgesinde çıkar ve termik santrallerde yakılır.\n• Taş Kömürü: I. Zaman (Paleozoik) tortuludur, yüksek kalori verdiği için demir-çelik sanayisinde (Karabük, Ereğli) kullanılır.\n• Krom: Paslanmaz çelik yapımında kullanılır (Elazığ-Guleman ve Antalya Ferrokrom tesisleri).\n• Fosfat: Gübre sanayisinde kullanılır (Mardin-Mazıdağı).\n\n💡 KPSS HAFIZA KARTI:\nMaden ve İşlendiği Yerler:\n• Boksit -> Konya / Seydişehir Alüminyum Tesisleri\n• Fosfat -> Mardin / Mazıdağı Gübre Fabrikası\n• Bakır -> Samsun (Liman/Ulaşım) ve Artvin Murgul.",
