    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Yozgat (Sorgun – Sarıkaya arası)\nTersiyer döneminde Anadolu'nun iç kesimlerindeki kapalı göllerin şiddetli buharlaşmayla kuruması sonucunda geriye kalan kimyasal tortul kayaç olan **JİPS (Alçı Taşı)** tabakalarına İç Anadolu'da en çok **Sivas Havzası, Çankırı ve Yozgat'ın Sorgun-Sarıkaya havzasında** rastlanır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Aydın (Çine): Menderes masifinin sert granit ve başkalaşım (gnays) kayalarıyla kaplıdır (Tor topografyası).\n• C) Ankara (Beypazarı): Trona (doğal soda) ve linyit havzasıdır.\n• D) Şanlıurfa (Siverek): Karacadağ'dan püsküren bazalt lav platosudur.\n• E) Sinop (Boyabat): Karadeniz fliş ve kumtaşı tabakalarıdır.\n\n💡 KPSS HAFIZA KARTI:\nJips (Alçı Taşı) Karstı Görülen İller:\n**Sivas** (En tipik jips mağaraları ve erime şekilleri), **Çankırı** ve **Yozgat** çevresi.",
