    "markedAnswer": "B",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Denizli\nDenizli ili; Büyük Menderes Graben fay zonu üzerinde yer aldığı için hem çok zengin **Fay (Jeotermal/Sıcak Su) kaynaklarına** sahiptir (Sarayköy Jeotermal Santrali - Türkiye'nin ilk jeotermal elektrik santrali); hem de arazisindeki kalkerli litolojik yapı sayesinde yer altından çıkan kalsiyum bikarbonatlı suların çökelmesiyle dünyaca ünlü **Pamukkale Travertenlerini oluşturan Karstik kaynaklara** ev sahipliği yapar.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A & B) Mersin ve Antalya: Karstik kaynaklar (Voklüz/Gürlek) yönünden çok zengindir ancak I. derece fay hatları üzerinde olmadıkları için jeotermal fay kaynakları zayıftır.\n• D) Trabzon: Karstik ve fay kaynakları yönünden fakirdir; yamaç kaynakları yaygındır.\n• E) Zonguldak: Taş kömürü havzası olup jeotermal kaynak zengini değildir.\n\n💡 KPSS HAFIZA KARTI:\nKaynak Türleri:\n• Voklüz (Karstik Kaynak) = Suları soğuk ve aşırı kireçlidir (Akdeniz - Manavgat).\n• Fay Kaynağı = Suları sıcak, mineralli, debisi yıl boyunca sabittir ve deprem bölgelerindedir (Ege Grabenleri, Güney Marmara).\n• Gayzer = Türkiye'de aktif volkanizma olmadığı için **KESİNLİKLE YOKTUR!**",
    "isMapQuestion": false,
