    "explanation": "✅ DOĞRU CEVAP: D) Podzolik Toprak – Çay\nÇay tarımı podzolik topraklarda değil; Doğu Karadeniz kıyılarında bol yağışla kireci yıkanmış, asit reaksiyonlu ve organik maddece zengin **Yıkanmış Kahverengi Orman Toprakları** üzerinde yapılır. **Podzol topraklar** ise Batı Karadeniz'in yüksek dağlarında, aşırı soğuk ve iğne yapraklı orman altında aşırı yıkanmış, kül renkli, besin değeri son derece düşük topraklardır; üzerinde çay tarımı yapılamaz.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Vertisol Toprak – Ayçiçeği: Doğrudur. Trakya (Ergene) havzasında \"Dönen Toprak / Taşdoğuran / Karakepir\" olarak bilinen killi topraktır; ayçiçeği için idealdir.\n• B) Terra Rossa – Zeytin: Doğrudur. Akdeniz ve Kıyı Ege'de kalker üzerindeki kırmızı renkli topraktır; zeytin ve turunçgil yetiştirilir.\n• C) Alüvyal Toprak – Mısır: Doğrudur. Deltalarda su tutma kapasitesi yüksek mineral zengini topraktır.\n• E) Kahverengi Step – Buğday: Doğrudur. İç Anadolu'nun yarı kurak bozkır toprağıdır; tahıl tarımına uygundur.\n\n💡 KPSS HAFIZA KARTI:\nVertisol (Karakepir / Dönen Toprak):\n• Killi kireçli göl tabanı toprağıdır.\n• Yazın kuruyup derin yarıklar açılır, içine dökülen taşlar kışın toprak ıslanıp şişince yukarı fırlar (\"Taşdoğuran\").\n• En çok görüldüğü yer: **Trakya (Ergene Havzası) ve Muş Ovası**.",
