    "questionText": "Karadeniz iklimi her mevsim yağışlı, yazları ılık, kışları serin geçen bir iklim tipidir.\nBuna göre, Marmara Bölgesi'nde yer alan;\nI. Yıldız (Istranca) Dağları'nın kuzey yamaçları\nII. Çatalca Kocaeli Platosu'nun Karadeniz kıyıları\nIII. Ergene Havzası\nIV. Güney Marmara kıyıları\nsahalarından hangilerinde Karadeniz iklim özellikleri belirgin olarak yaşanmaktadır?",
