    "questionText": "Aşağıda Türkiye'deki bir kentin sınırları içinde bulunan yer şekillerinden bazıları verilmiştir:\n- Traverten basamakları ve karstik platolar\n- Derin kanyon vadiler ve düdenler\n- Kıyı kumulları ve falezler\nBu yer şekillerinin tamamının görüldüğü il aşağıdakilerden hangisidir?",
