    "explanation": "✅ DOĞRU CEVAP: E) II ve IV (Hidroelektrik potansiyeli ve Derin vadiler)\nAkarsuların;\n• II. Hidroelektrik enerji potansiyelinin yüksek olması,\n• IV. Derin ve dik yamaçlı vadiler (kanyon veya çentik vadiler) açması,\ndoğrudan doğruya arazinin **YÜKSELTİSİ, EĞİMİ VE ENGEBESİ (Yer şekilleri / Jeomorfoloji)** ile ilgilidir.\nI (Debi azlığı) ve III (Sulamada kullanım) ise yağış miktarı ve yaz kuraklığı gibi **iklim şartlarına** bağlıdır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• Eğim ve Yükselti -> Akış hızını, hidroelektrik potansiyelini ve derine aşındırma gücünü artırır (II ve IV).\n• İklim ve Yağış -> Debiyi, su miktarını ve rejimi belirler (I ve III).\n\n💡 KPSS HAFIZA KARTI:\nHidroelektrik Potansiyel Sıralaması:\n1. Doğu Anadolu (En Yüksek - Yükselti ve eğim en fazla)\n2. Karadeniz\n3. Akdeniz\n...\n7. Marmara (En Düşük - Ortalama yükselti ve eğim en az).",
