    "topic": "Türkiye'nin Su Varlığı / Göller",
    "questionText": "Türkiye'de volkanik faaliyetlerin en fazla olduğu bölge Doğu Anadolu'dur. Bu bölgede volkanizmanın farklı etkilerine bağlı göller ortaya çıkmıştır.\n\nDoğu Anadolu'da bulunan aşağıdaki göllerden hangisinin oluşumunda volkanik faaliyetlerin etkisi yoktur?",
    "options": {
      "A": "Nemrut",
      "B": "Van",
      "C": "Çıldır",
      "D": "Haçlı",
      "E": "Aktaş"
    },
    "markedAnswer": "E",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Aktaş\nDoğu Anadolu'da volkanizma çok etkilidir ancak Ardahan ile Gürcistan sınırında yer alan **Aktaş (Hozapin) Gölü**, yer kabuğunun kırılmasıyla çöken çukurlukta suların birikmesiyle oluşmuş tamamen **TEKTONİK** kökenli bir göldür; oluşumunda volkanik faaliyetlerin etkisi yoktur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Nemrut Gölü: Nemrut Dağı'nın patlamasıyla tepe kısmında oluşan kalderada suların birikmesiyle meydana gelmiş Türkiye'nin en büyük **Volkanik Krater/Kaldera** gölüdür.\n• B) Van Gölü: Nemrut volkanından çıkan lavların Muş-Tatvan çöküntü oluğunu kapatmasıyla oluşmuş dünyanın en büyük **Volkanik Set (ve tektonik karma)** gölüdür.\n• C) Çıldır Gölü: Ardahan-Kars platosunda lav akıntılarının vadi önünü tıkamasıyla oluşan kışın buz tutan **Volkanik Set** gölüdür.\n• D) Haçlı (Bulanık) Gölü: Muş'ta volkanik kütlelerin dere yatağını kapatmasıyla oluşan tipik bir **Volkanik Set** gölüdür.\n\n💡 KPSS HAFIZA KARTI:\nDoğu Anadolu Volkanik Gölleri:\n• Kaldera Gölü = **Nemrut Gölü** (Bitlis).\n• Volkanik Set Gölleri = **\"BAÇE VAN HAM\"** (Balık, Çıldır, Erçek, Van, Haçlı, Nazik).\n• Dikkat Tuzağı: **Aktaş (Hozapin) Gölü Tektoniktir!**",
    "isMapQuestion": false,
    "file": "20260905_001956.jpg"
