    "questionText": "Sanayi ve ticaret faaliyetlerinin yoğun olduğu yerler insanlara geniş iş imkânları sunduğu için nüfusun da kalabalık olduğu yörelerdir.\n\nAşağıdaki yerleşmelerden hangisinde nüfus yoğunluğunun fazla olması bu durumla açıklanamaz?",
    "options": {
      "A": "İzmit",
      "B": "Denizli",
      "C": "Soma",
      "D": "Bursa",
      "E": "Gaziantep"
    },
    "markedAnswer": "C",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Soma\nManisa'nın Soma ilçesinde nüfusun yoğunlaşmasının ve kentin hızla büyümesinin ana sebebi sanayi veya ticaret değil; zengin **LİNYİT KÖMÜRÜ** yataklarının işletilmesi ve linyite dayalı termik santrallerin bulunması, yani **MADENCİLİK** fonksiyonudur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İzmit (Kocaeli): Petrokimya (Tüpraş), otomotiv yan sanayi, kağıt ve makine sanayisiyle Türkiye'nin en büyük sanayi merkezlerindendir.\n• B) Denizli: Dokuma, havlu-bornoz, tekstil sanayisi ve buna bağlı dış ticaretle nüfus çekmiştir.\n• D) Bursa: Otomotiv devi (Tofaş, Renault), tekstil, mobilya ve gıda sanayisiyle sanayi/ticaret metropolüdür.\n• E) Gaziantep: Güneydoğu'nun sanayi ve ticaret başkentidir (Devasa OSB'ler, makine halısı, iplik ve gıda ihracatı).\n\n💡 KPSS HAFIZA KARTI:\nFonksiyonuna Göre Şehirler:\n• Maden Şehirleri: **Soma (Linyit), Zonguldak (Taş kömürü), Batman (Petrol), Tavşanlı (Linyit), Divriği (Demir), Yatağan (Linyit), Murgul (Bakır)**.\n• Sanayi / Ticaret Şehirleri: **İzmit, Bursa, Denizli, Gaziantep, Kayseri, Eskişehir**.",
