    "explanation": "✅ DOĞRU CEVAP: C) Gölün kuruyan alanlarını sulu tarıma açmak\nBurdur Gölü kapalı havzada yer alan ve aşırı buharlaşma, kuraklık ile gölü besleyen dereler üzerine göletler yapılması sonucu hızla su kaybeden bir ekosistemdir. Gölün kuruyan çanak alanlarını sulu tarıma açmak; yonca, mısır gibi çok su tüketen ürünlerin ekilmesine, ilave yüzlerce derin sondaj kuyusu açılmasına ve yer altı su tablasının büsbütün çökmesine yol açar. Bu uygulama gölü kurtarmaz, yok oluşunu hızlandırır!\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Gölü besleyen akarsuların göle akıtılması: Gölün su bilançosunu pozitif yönde toparlar.\n• B) Sondajların sınırlandırılması: Tabandaki yer altı suyunun göl seviyesinin altına inmesini engeller.\n• D) Damla sulama yapılması: Vahşi sulamadaki %60'a varan su israfını önleyerek tatlı su rezervlerini korur.\n• E) Yeraltı suyu kullanımının azaltılması: Göle doğru yeraltı su akışını destekler.\n\n💡 KPSS HAFIZA KARTI:\nBurdur Gölü Özellikleri:\n• Oluşumu: **Tektonik**.\n• Kimyasal Yapısı: Gideğeni olmadığı için **Acı-Tuzlu / Sodyumlu**.\n• Statüsü: **Ramsar Alanı**.\n• Canlı Varlığı: Tatlı su balığı yaşayamaz; endemik **Burdur Dişli Sazancığı** yaşar.",
