    "topic": "Türkiye'nin Ulaşım Coğrafyası / Yüksek Hızlı Tren (YHT) Hatları",
    "questionText": "Türkiye'de demir yollarının kara yollarına göre daha az tercih edilmesinin en önemli nedeni, konvansiyonel hatlarda çalışan trenlerin düşük hızda ilerlemesidir. Bu sorunun çözümü ve demir yollarının yolcu ve yük taşımacılığındaki payının artırılması amacıyla büyük kentleri birbirine bağlayan güzergâhlarda hızlı tren hatları yapılmıştır.\n\nAşağıdakilerden hangisi bu hatlardan biri değildir?",
    "options": {
      "A": "Konya-Karaman",
      "B": "Ankara- Eskişehir",
      "C": "Eskişehir-İstanbul",
      "D": "Yozgat-Sivas",
      "E": "Eskişehir-Bursa"
    },
    "markedAnswer": "E",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Eskişehir - Bursa\nTürkiye'de inşaatı devam eden ve henüz faaliyete geçmemiş olan hat **Eskişehir - Bursa (Bursa-Osmaneli YHT hattı)** projesidir. Tünel ve altyapı çalışmaları sürmekte olup Bursa henüz demir yolu ve YHT ağına bağlanmamıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Konya - Karaman YHT: 2022 yılında işletmeye açılmış aktif yüksek hızlı tren hattıdır.\n• B) Ankara - Eskişehir YHT: 2009 yılında Türkiye'nin hizmete giren İLK Yüksek Hızlı Tren hattıdır.\n• C) Eskişehir - İstanbul YHT: 2014 yılında tamamlanarak Ankara-İstanbul bağlantısını sağlayan aktif hattır.\n• D) Yozgat - Sivas YHT: 2023 yılında Ankara-Kırıkkale-Yozgat-Sivas güzergahıyla açılan en yeni YHT hattıdır.\n\n💡 KPSS HAFIZA KARTI:\nYüksek Hızlı Tren (YHT) Kronolojisi:\n• İlk Açılan YHT Hattı: **Ankara - Eskişehir (2009)**\n• En Son Açılan Büyük Hat: **Ankara - Kırıkkale - Yozgat - Sivas (2023)**\n• İşletmedeki Hatlar: Ankara, Eskişehir, Bilecik, Sakarya, Kocaeli, İstanbul, Konya, Karaman, Kırıkkale, Yozgat, Sivas.\n• Yapımı Süren Önemli Hatlar: **Ankara-Afyon-İzmir, Bandırma-Bursa-Osmaneli, Mersin-Adana-Gaziantep**.",
    "isMapQuestion": false,
    "file": "20260905_001505.jpg"
