    "explanation": "✅ DOĞRU CEVAP: D) Irak\nBaşkenti Bağdat olup Habur Sınır Kapısı üzerinden ticaret yapılır; Türkiye'nin komşuları arasında en fazla ihracat yaptığı ülkedir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Başkenti Şam'dır; yaşanan iç karışıklıklar nedeniyle Türkiye ile ticareti büyük ölçüde gerilemiştir.\n• B) Başkenti Tahran'dır; yüzölçümü Türkiye'den büyüktür ve Türkiye bu ülkeden yoğun olarak doğal gaz ithal eder (dış ticaret açığı verir).\n• C) Başkenti Tiflis'tir; Sarp Sınır Kapısı ile bağlanır ancak ihracat hacmimiz Irak kadar yüksek değildir.\n• E) Başkenti Erivan'dır; siyasi sebeplerle doğrudan sınır ticareti kapalıdır.",
