    "questionText": "İzmir'in Çeşme ilçesinde yaşayan Erdal Bey, mutfak penceresinden haziran ayında batmakta olan Güneş'i izlerken Güneş'in adanın tam arkasından battığını görmüştür. Aynı pencereden eylül ayında Güneş'in batışını izleyen Erdal Bey, Güneş'in adanın yan tarafından denizin üzerinden battığını fark etmiştir.\n\nBuna göre, Erdal Bey'in haziran ve eylül aylarında Güneş'in farklı noktalardan battığını görmesinin temel nedeni aşağıdakilerden hangisidir?",
    "options": {
      "A": "Dünya'nın kendi ekseni etrafında batıdan doğuya doğru dönmesi",
      "B": "Yer ekseni ile yörünge düzlemi arasında 23°27' açı olması",
      "C": "Dünya'nın şeklinin kutuplardan basık ekvatordan şişkince olması",
      "D": "Yer ekseninin ekvator düzlemini dik açı ile kesmesi",
      "E": "Dünya'nın güneş çevresinde dolanırken izlediği yolun daire şeklinde değil elips olması"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Yer ekseni ile yörünge düzlemi arasında 23°27' açı olması\nEksen eğikliği (23°27') ve yıllık hareket sonucunda Güneş ışınlarının yeryüzüne düşme açısı ve Güneş'in doğuş-batış yerleri yıl boyunca ufukta yer değiştirir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Dünya'nın günlük hareketi batıdan doğuya dönmesiyle ilgilidir; Güneş'in doğudan doğup batıdan batmasını sağlar ancak yıl içindeki ufuk kaymasını açıklamaz.\n• C) Geoit şekil yerçekimi, ekvator-kutuplar yarıçapı ve çizgisel hız farklarını açıklar; doğuş-batış noktasını etkilemez.\n• D) Yer ekseni Ekvator düzlemine diktir (90°); burada kastedilen yörünge düzlemi (ekliptik) ile olan eğikliktir.\n• E) Yörüngenin elips olması Dünya'nın Güneş'e olan mesafesini, hızını ve mevsim sürelerini etkiler; batış yerinin ufukta kayması eksen eğikliğinden kaynaklanır.",
    "isMapQuestion": false,
    "file": "20260914_223030.jpg"
