    "questionText": "Yukarıdaki Türkiye haritasında numaralandırılarak gösterilen alanlardan hangisinde 2500 metrenin üzerinde güncel aktif buzul bulunmadığı halde Kuaterner buzul aşındırma ve biriktirme şekillerine rastlanır?",
