    "explanation": "✅ DOĞRU CEVAP: A) I ve II\nKaradeniz kıyılarında 500 m yüksekliğe kadar olan alçak kuşakta geniş yapraklı gür ormanların altında humusça zengin Kahverengi Orman Toprakları (I) ile vadi tabanları ve Bafra/Çarşamba gibi delta sahalarında akarsuların biriktirdiği Alüvyal Topraklar (II) yaygındır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Çernezyom toprakları (kara topraklar) Erzurum-Kars ve Ardahan'ın yüksek platolarında yaz yağışlarıyla yeşeren çayırlar altında görülür; Karadeniz sahilinde bulunmaz.\n• C) III (Çernezyom) Karadeniz sahil kuşağında yer almaz.\n• D) Podzol topraklar Karadeniz'de 1000-1200 metre üzerindeki soğuk, nemli ve iğne yapraklı orman kuşağında yıkanmış olarak görülür; 500 metre altında yaygın değildir.\n• E) Çernezyom ve podzol alçak sahil kuşağında birlikte görülmez.",
