    "questionText": "Türkiye'de köy altı yerleşmeleri geçici ve sürekli olmak üzere ikiye ayrılır.\n• Doğu Anadolu'da genellikle taş yapılı barınaklardan oluşan ve küçükbaş hayvancılık yapılan geçici yerleşmelerdir.\n• Genellikle Toroslar'da göçebe yörük ailelerin çadır kurarak hayvancılık yaptıkları geçici yerleşmelerdir.\n• Köyün uzağında küçükbaş hayvanların geceyi geçirmesi için etrafı çit veya taş duvarla çevrili barınaklardır.\n• Geniş tarım arazisi üzerine kurulu, hem tarım hem de hayvancılık faaliyetlerinin birlikte yapıldığı sürekli yerleşmelerdir.\n\nYukarıda verilen özellikler arasında aşağıdaki köy altı yerleşmelerinden hangisinin tanımı yer almaz?",
