    "explanation": "✅ DOĞRU CEVAP: D) I ve II\nGünümüz Türkiye'sinde uygulanan nüfus politikası; hem nüfusun eğitim ve sağlık kalitesini yükselterek niteliğini artırmayı (I), hem de doğum oranlarındaki sert düşüşü engelleyerek artış hızını dengeli biçimde yükseltmeyi (II) amaçlar.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Yalnız I eksiktir; devlet sadece niteliği değil, doğurganlığı teşvik ederek niceliği (genç nüfus oranını) korumayı da hedefler.\n• B) Yalnız II eksiktir; nitelikli iş gücü, eğitim ve sağlık hizmetleri de nüfus politikasının vazgeçilmez ayağıdır.\n• C) III antidemokratik olup günümüz hukuk devleti anlayışında ve Türkiye'nin kalkınma planlarında zorunlu iç iskân yer almaz.\n• E) III günümüz devlet politikalarında yer almaz.",
