    "questionText": "Türkiye'de demir madeni ile ilgili olarak aşağıda verilen yargılardan hangileri doğru değildir?\nI. En önemli çıkarım alanları Sivas (Divriği) ve Malatya (Hekimhan, Hasançelebi)'dır.\nII. Çıkarılan maden Karabük, Ereğli ve İskenderun'daki demir-çelik fabrikalarında işlenir.\nIII. Türkiye dünya demir cevheri rezervlerinde ilk sırada yer alır.\nIV. Demir işletme tesisleri yalnızca madenin çıkarıldığı alanların hemen yanına kurulmuştur.",
    "options": {
      "A": "I ve II",
      "B": "I ve III",
      "C": "II ve III",
      "D": "II ve IV",
      "E": "III ve IV"
    },
    "markedAnswer": "E",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) III ve IV\nIII yanlıştır çünkü Türkiye dünya demir rezervinde ilk sırada değildir, ağır sanayisinin ihtiyacını karşılamak için dışarıdan demir ithal eder. IV de yanlıştır çünkü Ereğli ve Karabük'te demir madeni çıkmaz; bu fabrikalar enerji kaynağına (taş kömürüne) yakınlık nedeniyle oraya kurulmuş olup demir başka sahalardan buralara taşınarak işlenir. Bu nedenle III ve IV doğru değildir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) I ve II demir madeni için son derece doğru temel bilgilerdir (yanlış değildir).\n• B) I doğrudur, III yanlıştır.\n• C) II doğrudur, III yanlıştır.\n• D) II doğrudur, IV yanlıştır.",
    "isMapQuestion": false,
