    "explanation": "✅ DOĞRU CEVAP: D) Kruvaziyer turizmi\nKruvaziyer turizmi, büyük yolcu gemileriyle deniz rotalarında yapılan ve modern liman altyapısına (İstanbul Galataport, Kuşadası vb.) dayanan bir turizm türüdür; kara topoğrafyası veya yer şekillerinin bir sonucu değildir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Fay hatları, kırıklı jeolojik yapı ve jeotermal sıcak su kaynaklarına doğrudan bağlıdır.\n• B) Yüksek dağların jeomorfolojik yapısına, yamaç eğimine ve kar tutma potansiyeline doğrudan bağlıdır.\n• C) Sarp dağ sıraları, kanyonlar ve engebeli jeomorfolojik yer şekillerine doğrudan bağlıdır.\n• E) Falez, volkan konisi, kanyon, mağara, traverten gibi kayaç ve yer şekillerini doğrudan ziyaret etmeyi amaçlar.",
