    "explanation": "✅ DOĞRU CEVAP: C) İnce Minareli Medrese\nİnce Minareli Medrese Konya il merkezinde yer alır. Ankara-Kars Turistik Doğu Ekspresi Ankara'dan doğuya (Kırıkkale-Kayseri-Sivas-Erzincan-Erzurum-Kars) doğru ilerler; Konya bu trenin güzergâhında yer almaz.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Ani Harabeleri trenin son durağı olan Kars ili sınırları içinde yer alır ve mutlaka ziyaret edilir.\n• B) Divriği Ulu Camii ve Darüşşifası, trenin Sivas Divriği durağında yolcuların gezdiği başlıca UNESCO dünya mirasıdır.\n• D) Çifte Minareli Medrese trenin uzun mola verdiği Erzurum il merkezinde yer alır.\n• E) Sivas Kongresi'nin yapıldığı Atatürk Kongre ve Etnografya Müzesi, trenin Sivas merkez durağında ziyaret edilir.",
