    "questionText": "Pamuklu dokuma sanayisi, pamuk tarımının yapıldığı alanlarda hammaddeye yakınlık ilkesine göre veya tüketici nüfusun ve pazarın yoğun olduğu metropollerde kurulur.\n\nBuna göre, yukarıdaki haritada numaralandırılmış illerden hangisinde pamuklu dokuma sanayisinin bulunması hammaddeye yakınlıkla açıklanamaz (pamuk o yörede yetiştirilmez)?\n(I: Manisa, II: Antalya, III: Kayseri, IV: Adana, V: Şanlıurfa)",
