    "questionText": "Türkiye'de peri bacaları, traverten basamakları, derin kanyon vadiler ve karstik mağaralar gibi yer şekilleri turizmin çeşitlenmesine büyük katkı sağlamaktadır.\n\nAşağıdaki turizm türlerinden hangisinin gelişiminde bu tip jeomorfolojik yer şekillerinin doğrudan bir payı olduğu söylenemez?",
