    "explanation": "✅ DOĞRU CEVAP: C) Kültür turizmi\nKültür turizmi; insan eliyle inşa edilmiş tarihi yapılar, arkeolojik antik kentler, müzeler, inanç merkezleri ve etnografik yaşam tarzını konu edinir; doğal jeomorfolojik yer şekilleri beşeri/kültürel değil fiziki kökenlidir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Doğal peyzajları koruma ve doğa ile uyumlu gezileri kapsayan ekoturizme doğrudan zemin oluşturur.\n• B) Kayaç yapılarını, aşınım-birikim şekillerini ve jeolojik oluşumları inceleyen jeoturizmin ana konusudur.\n• D) Eşsiz manzaraları görme, seyretme ve fotoğraflama odaklı doğa turizmini doğrudan canlandırır.\n• E) Kanyon geçişi (canyoning), mağara keşfi ve kaya tırmanışı gibi doğa sporları ve macera turizmine ortam hazırlar.",
