    "topic": "Osmanlı Devleti Duraklama Dönemi (XVII. Yüzyıl Islahatları)",
    "questionText": "Aşağıdakilerden hangisi XVII. yüzyıl Osmanlı ıslahatçılarından biri değildir?",
    "options": {
      "A": "Tarhuncu Ahmet Paşa",
      "B": "II. Osman",
      "C": "Köprülü Mehmet Paşa",
      "D": "IV. Murat",
      "E": "I. Mahmut"
    },
    "markedAnswer": "E",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) I. Mahmut\nI. Mahmut, XVIII. yüzyıl (18. yy / Gerileme Dönemi) padişahıdır. Batı tarzı ilk askeri ıslahat olan Hendesehane'yi (Kara Mühendishanesi) açmış ve Fransız subay Humbaracı Ahmet Paşa'ya (Comte de Bonneval) orduyu reorganize ettirmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Tarhuncu Ahmet Paşa: XVII. yüzyılda (IV. Mehmet dönemi) Osmanlı tarihindeki İLK modern bütçeyi (denk bütçe) hazırlayan sadrazamdır.\n• B) II. Osman (Genç Osman): XVII. yüzyılda ilk ciddi ıslahat hareketini başlatan, Yeniçeri Ocağı'nı kaldırmayı düşündüğü için yeniçerilerce şehit edilen padişahtır.\n• C) Köprülü Mehmet Paşa: XVII. yüzyılda şartlar öne sürerek sadrazamlığa gelen ilk Osmanlı devlet adamıdır (Köprülüler Duraklama içinde Yükselme dönemi yaşatmıştır).\n• D) IV. Murat: XVII. yüzyılda içki ve tütünü yasaklayan, gece sokağa çıkma yasağı koyan, Koçi Bey ve Kâtip Çelebi'ye devletin gerileme nedenleri üzerine ilk risaleleri hazırlatan padişahtır.\n\n💡 KPSS HAFIZA KARTI:\nXVII. Yüzyıl (17. yy) Islahatçıları Şifresi: **TOKMAC** -> **T**arhuncu, **O**sman (Genç), **K**öprülüler, **M**urat (IV), **A**hmet (I), **C**elaliler ile mücadele edenler.",
    "isMapQuestion": false,
