    "topic": "İlk Türk Devletleri",
    "questionText": "359 - 372 yılları arasında Kafkaslardan Anadolu içlerine kadar girmişlerdir. Urfalı Piskopos Ephraem (Efrahim) ---- hakkında “Bunlar Yec’üc ve Mec’üc’ün atlılarıdır. Atlarının üzerinde fırtına gibi uçarlar.” demiştir.\n\nBuna göre metinde verilen boşluğa aşağıdakilerden hangisi getirilmelidir?",
    "options": {
      "A": "İskitler",
      "B": "Göktürkler",
      "C": "Hazarlar",
      "D": "Uygurlar",
      "E": "Hunlar"
    },
    "markedAnswer": "B",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Hunlar\n375 yılındaki Kavimler Göçü sonrasında Balamir, Uldız ve Kursık dönemlerinde Avrupa Hunları Kafkaslar üzerinden geçerek Erzurum, Malatya ve Antakya'ya kadar uzanan ilk Anadolu akınlarını gerçekleştirmiştir. Süryani kaynaklarında bu akınlar \"Yecüc ve Mecüc atlıları\" olarak kaydedilmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İskitler (Sakalar): M.Ö. VII. yüzyılda Anadolu'ya gelen ilk Türk topluluğudur (Alp Er Tunga ve Tomris Hatun ile bilinir; Bozkırın Kuyumcuları olarak tanınır).\n• B) Göktürkler: Orta Asya merkezli büyük imparatorluk kurmuş, hiçbir zaman Kafkaslar üzerinden Anadolu içlerine inmemiştir.\n• C) Hazarlar: Kafkasya ve Karadeniz'in kuzeyinde Museviliği kabul eden tek Türk devletidir; Hz. Osman döneminde İslam ordularının Kafkaslara ilerleyişini durdurmuştur.\n• D) Uygurlar: Tarım havzası ve İç Asya'da Maniheizm dinini kabul ederek yerleşik hayata geçen, matbaa ve fresk sanatını geliştiren Türk devletidir.\n\n💡 KPSS HAFIZA KARTI:\nAnadolu'ya Türk Akınları Sıralaması:\n1. İskitler (M.Ö. 7. yy - Yerleşme amaçsız)\n2. Avrupa Hunları (395-398 Uldız dönemi - Yerleşme amaçsız)\n3. Sabirler (6. yy)\n4. Selçuklular (11. yy - Çağrı Bey ile keşif, Malazgirt ile kalıcı yurt edinme).",
    "isMapQuestion": false,
