    "questionText": "İslam öncesi Türklerde vatan sevgisinden bahseden ilk Türk hükümdarı aşağıdakilerden hangisidir?",
    "options": {
      "A": "Teoman",
      "B": "Mete Han",
      "C": "Çiçi",
      "D": "Kutluk Kağan",
      "E": "Bilge Kağan"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Mete Han\nAsya Hun Devleti hükümdarı Mete Han, komşu Tunguzların (Donghu) kendisinden sırasıyla iyi koşan atını ve eşini istemesi üzerine barış adına vermiş; ancak sınırdaki çorak bir toprak parçasını istediklerinde \"Toprak milletindir, onu kimse veremez!\" diyerek savaş açmış ve vatan sevgisinden bahseden ilk Türk lider olmuştur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Teoman: Asya Hun Devleti'nin tarihte bilinen İLK hükümdarıdır (M.Ö. 220). Çin Seddi onun akınlarına karşı inşa edilmeye başlanmıştır.\n• C) Çi-çi: Asya Hun Devleti'nde kardeşi Ho-han-ye'nin Çin hakimiyetine girme teklifini \"alçaklık ve utanç verici\" bularak bağımsızlık mücadelesi veren Hun lideridir.\n• D) Kutluk Kağan: 682 yılında Çin esaretinden kurtularak II. Göktürk Devleti'ni kuran ve \"İlteriş\" unvanını alan hükümdardır.\n• E) Bilge Kağan: II. Göktürk Devleti'nin en parlak dönem hükümdarıdır; adına Orhun Abideleri dikilmiştir.\n\n💡 KPSS HAFIZA KARTI:\nMete Han: İlk düzenli Türk ordusu (Onlu Teşkilat - M.Ö. 209 Kara Kuvvetleri kuruluş yılı), Islıklı ok, Çin'i vergiye bağlama (Paiteng Savaşı), Türk boylarını tek bayrak altında toplama.",
