    "markedAnswer": "E",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Hasan Sabbah\n1090 yılında İran'daki sarp Alamut Kalesi'ni ele geçiren Hasan Sabbah, Şii-İsmailiye mezhebi temelli \"Bâtınilik\" hareketini kurmuştur. Cennet vaadi ve uyuşturucuyla kandırdığı fedaileri (Haşhaşiler) aracılığıyla Büyük Selçuklu veziri Nizamülmülk dahil pek çok hükümdar, komutan ve alime suikast düzenlemiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Romen Diyojen: 1071 Malazgirt Savaşı'nda Sultan Alparslan'a mağlup olup esir düşen Bizans İmparatorudur.\n• C) Ömer Hayyam: Selçuklu döneminde yaşamış rubaileriyle ünlü şair, filozof ve matematikçidir; Sultan Melikşah adına \"Celali Takvimi\"ni hazırlayan heyetin başkanıdır.\n• D) Hülagü Han: İlhanlı Devleti'nin kurucusu olan Moğol hükümdarıdır; 1256'da Alamut Kalesi'ni yerle bir ederek Bâtınilere son vermiş, 1258'de Bağdat'ı işgal edip Abbasi Halifeliğini yıkmıştır.\n• E) Sadeddin Köpek: Türkiye Selçuklu Devleti'nde I. Alaeddin Keykubat ve II. Gıyaseddin Keyhüsrev dönemlerinde etkili olmuş, devlet adamlarını tasfiye ettiren entrikacı vezirdir.\n\n💡 KPSS HAFIZA KARTI:\nBâtıniliğin Doğuşu: Hasan Sabbah (Alamut Kalesi) | En büyük kurbanı: Nizamülmülk | Bâtınileri tamamen yok eden: İlhanlı Hükümdarı Hülagü Han.",
