    "questionText": "Türkiye Selçuklularında donanma komutanına verilen unvan aşağıdakilerden hangisidir?",
    "options": {
      "A": "Emir-i Sevahil",
      "B": "Subaşı",
      "C": "Melikü's Sevahil",
      "D": "Reisülbahr",
      "E": "Kaptanı Derya"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Reisülbahr (veya Melikü's-Sevahil / Emir-i Sevahil)\nTürkiye Selçuklularında deniz kuvvetleri komutanına \"Reisü'l-Bahr\" (Deniz Reisi) ya da kıyıların meliki anlamında \"Melikü's-Sevahil\" unvanı verilmiştir. Selçuklular Sinop, Alanya, Antalya ve Suğdak'ta tersaneler kurmuşlardır. (Soru seçeneklerinde doğrudan D şıkkı hedeflenmiştir).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A & C) Emir-i Sevahil / Melikü's Sevahil: Türkiye Selçuklularında deniz kıyılarını ve liman savunmasını yöneten sahil beylerine verilen diğer unvandır.\n• B) Subaşı: Selçuklu ve Osmanlı'da şehir ve kasabaların asayişinden, güvenliğinden ve gece bekçilerinden sorumlu askeri komutandır.\n• E) Kaptan-ı Derya (Kaptanıderya): Osmanlı Devleti'nde donanmanın en üst rütbeli komutanına verilen unvandır (İlk Kaptan-ı Derya Saruca Paşa, Divan-ı Hümayun üyesi olan ilk Kaptan-ı Derya ise Barbaros Hayrettin Paşa'dır).\n\n💡 KPSS HAFIZA KARTI:\nDeniz Komutanları Karşılaştırması:\n• Selçuklu: Reisü'l-Bahr / Melikü's-Sevahil\n• Osmanlı: Kaptan-ı Derya (Derya Kaptanı)\n• İlk Türk Denizcisi: Çaka Bey (1081)",
