    "subjectNumber": 39,
    "categoryOrder": 4,
    "category": "Osmanlı Devleti — Kuruluş ve Yükselme Dönemi",
    "topic": "Osmanlı Kültür ve Medeniyeti / Bilim İnsanları",
    "questionText": "Fatih Sultan Mehmet Dönemi'nde yaşamış olan ve Türk İslam tarihinde ilk kez tıp alanında Türkçe olarak kaleme alınan \"Mücerrebname\" adlı eseriyle tanınan ünlü Türk cerrahı ve hekimi aşağıdakilerden hangisidir?",
    "options": {
      "A": "Akşemseddin",
      "B": "Ali Kuşçu",
      "C": "Ahi Çelebi",
      "D": "Altuncuzade",
      "E": "Sabuncuoğlu Şerafeddin"
    },
    "markedAnswer": "E",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Sabuncuoğlu Şerafeddin\nFatih Sultan Mehmet döneminde yaşayan ve Amasya Darüşşifası'nda hekimlik yapan Sabuncuoğlu Şerafeddin, Türk-İslam tarihindeki ilk Türkçe cerrahi eser olan **\"Cerrâhiyyetü'l-Hâniyye\"** kitabını yazmıştır. Eserinde ameliyat tekniklerini, cerrahi müdahaleleri ve kullandığı aletlerin renkli resimlerini bizzat çizmiş; çocuk hastalıkları için \"Mücerrebname\"yi kaleme almıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Akşemseddin: Fatih'in hocasıdır; mikrobiyolojinin öncüsü sayılır, mikrobu ilk kez \"Maddetü'l-Hayat\" eserinde tanımlamıştır.\n• B) Ali Kuşçu: Semerkant'tan Fatih'in davetiyle İstanbul'a gelen, Ayasofya Medresesi başmüderrisi olan ünlü matematik ve astronomi bilginidir (\"Risale fi'l-Hey'e\").\n• C) Ahi Çelebi: II. Bayezid devrinin ünlü hekimidir; böbrek ve mesane taşları üzerine yazdığı \"Risale fi'l-Hasa\" ile tanınır.\n• D) Altuncuzade: Fatih döneminde idrar yolu hastalıkları ve mesane operasyonları üzerine uzmanlaşmış cerrahtır.\n\n💡 KPSS HAFIZA KARTI:\nFatih Dönemi Bilim İnsanları:\n• Cerrahi ve Ameliyat resimleri = Sabuncuoğlu Şerafeddin\n• Matematik ve Astronomi = Ali Kuşçu\n• Mikrop ve Tıp/Tasavvuf = Akşemseddin",
    "isMapQuestion": false,
    "file": "20260904_233827.jpg"
