    "explanation": "✅ DOĞRU CEVAP: D) Şahkulu İsyanı (1511)\nŞahkulu İsyanı, Kanuni Sultan Süleyman döneminde değil; babası Yavuz Sultan Selim'den de önceki padişah olan **II. Bayezid** döneminde (1511 yılında) Şii Safevilerin kışkırtmasıyla Antalya ve Teke yöresinde çıkmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Ahmet Paşa İsyanı (1524): Kanuni döneminde Mısır'a vali tayin edilen Hain Ahmet Paşa'nın sadrazam olamadığı için Mısır'da sultanlığını ilan etmesiyle çıkan isyandır.\n• B) Kalenderoğlu İsyanı (1527): Kanuni döneminde Anadolu'da tımarları ellerinden alınan derviş ve sipahilerin katıldığı dini-sosyal içerikli Celali isyanıdır.\n• C) Baba Zünnun İsyanı (1526): Kanuni devrinde Yozgat ve Bozok çevresinde haksız vergi tarhı yüzünden patlak veren Türkmen isyanıdır.\n• E) Canberdi Gazali İsyanı (1521): Kanuni'nin tahta çıkışını fırsat bilerek Memlük Devleti'ni yeniden diriltmek amacıyla Şam'da çıkan isyandır.\n\n💡 KPSS HAFIZA KARTI:\nKanuni Dönemi İç İsyanları Şifresi: **CAN-BA-KA**\n• **Can**berdi Gazali (Şam - Memlük'ü diriltme)\n• **A**hmet Paşa (Mısır valisi)\n• **Ba**ba Zünnun (Yozgat - Vergi)\n• **Ka**lenderoğlu (Anadolu - Mezhebi/Tımar)",
