    "explanation": "✅ DOĞRU CEVAP: B) Ankara - II. Kosova\nVerilen kronolojik sıralamada:\n• 1364: Sırpsındığı Savaşı (I. Murat dönemi - İlk Haçlı zaferi)\n• 1389: I. Kosova Savaşı (I. Murat dönemi - Haçlılar yenildi)\n• **1402: Ankara Savaşı** (Yıldırım Bayezid ile Timur arasında yapıldı, Osmanlı yenildi ve Fetret Devri başladı)\n• **1448: II. Kosova Savaşı** (II. Murat dönemi - Haçlılar kesin hezimete uğradı, Türklerin Balkanlar'dan atılamayacağı kesinleşti).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Koyunhisar (Bafeus - 1302): Osman Bey'in Bizans tekfurlarına karşı kazandığı İLK savaştır.\n• C) Pelekanon (Maltepe - 1329): Orhan Bey'in Bizans İmparatoru III. Andronikos'u mağlup ederek İznik'in fethini sağladığı savaştır.\n• D) Varna Savaşı (1444): II. Murat'ın tahta tekrar dönerek Haçlıları bozguna uğrattığı savaştır.\n• E) Niğbolu Savaşı (1396): Yıldırım Bayezid'in Haçlı ordusunu imha ettiği ve \"Sultan-ı İklim-i Rum\" unvanını aldığı savaştır.\n\n💡 KPSS HAFIZA KARTI:\nII. Kosova Savaşı'nın (1448) Tarihi Önemi:\nMiryokefalon Anadolu için ne ise, II. Kosova Balkanlar için odur!\nBu zaferle Türklerin Balkanlar'daki varlığı kesinleşmiş, Avrupalılar savunmaya çekilmiştir.",
