    "explanation": "✅ DOĞRU CEVAP: A) III. Ahmet (Lale Devri)\n1718 Pasarofça Antlaşması ile başlayıp 1730 Patrona Halil İsyanı ile biten \"Lale Devri\" Padişahı III. Ahmet'tir (Sadrazamı Nevşehirli Damat İbrahim Paşa). Bu dönemde:\n1. Avrupa'ya ilk kez geçici elçilikler açılmış (Paris'e Yirmisekiz Mehmet Çelebi gönderilmiş),\n2. İbrahim Müteferrika ve Said Efendi tarafından ilk Osmanlı Müslüman matbaası kurulmuştur (1727).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) I. Mahmut: Lale Devri'nden sonra tahta çıkan ve Batı tarzı ilk askeri okul olan \"Hendesehane\"yi (Kara Mühendishanesi) açan padişahtır.\n• C) III. Mustafa: Baron de Tott'a Sürat Topçuları Ocağı'nı kurduran ve ilk iç borçlanma sistemi olan Esham Senetleri'ni hazırlatan padişahtır.\n• D) I. Abdülhamit: Cülus bahşişini kaldıran, ulufe alım-satımını yasaklayan ve İstihkam Okulu'nu açan padişahtır.\n• E) III. Selim: Nizam-ı Cedid yeniliklerini başlatan ve Avrupa'da ilk DAİMİ elçilikleri (Londra) açan padişahtır.\n\n💡 KPSS HAFIZA KARTI:\nLale Devri'nin İlkleri:\n• İlk geçici elçi: Yirmisekiz Mehmet Çelebi (Paris)\n• İlk matbaa: İbrahim Müteferrika (Dini eser basımı hariç)\n• İlk itfaiye teşkilatı: Tulumbacılar Ocağı\n• İlk çiçek aşısı uygulaması (Doğu'dan örnek alınmıştır).",
    "isMapQuestion": false,
