    "topic": "Osmanlı Kültür ve Medeniyeti / Devlet Yönetimi ve İlmiye Sınıfı",
    "questionText": "Osmanlı Devleti'nde Divan-ı Hümayun'da alınan kararların dine uygunluğunu denetleyen ve adalet işlerine bakan görevliler ilmiye sınıfına mensuptur.\n\nBuna göre aşağıda verilen Divan üyelerinden hangisi medrese çıkışlı olmak zorundadır?",
    "options": {
      "A": "Sadrazam",
      "B": "Nişancı",
      "C": "Kazasker",
      "D": "Reisülküttap",
      "E": "Defterdar"
    },
    "markedAnswer": "C",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Kazasker (Kadıasker)\nOsmanlı Devleti'nde yönetim sınıflarından **İlmiye (Ulema)** sınıfının zirvesinde yer alan Kazaskerler; adalet (kadı atamaları), eğitim (müderris tayinleri) ve din işlerinden sorumludur. İlmiye sınıfına mensup olmanın KESİN ŞARTI: **Doğuştan Müslüman, Türk kökenli ve Medrese mezunu** olmaktır. Devşirmeler asla Kazasker veya Şeyhülislam olamaz!\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Sadrazam: Seyfiye (kılıç/asker) sınıfındandır; Enderun'dan yetişen devşirme kökenliler de sadrazam olabilir (Sokullu, Köprülü vb.).\n• B) Nişancı: Kalemiye (bürokrasi) sınıfındandır; fermanlara tuğra çeker, tahrir defterlerini tutar.\n• D) Reisülküttap: Kalemiye sınıfındandır; dışişleri bakanıdır (diplomasi).\n• E) Defterdar: Kalemiye sınıfındandır; devletin maliye ve hazine bakanıdır.\n\n💡 KPSS HAFIZA KARTI:\nOsmanlı Yönetici Sınıfları ve Köken Kuralı:\n• **Seyfiye** (Sadrazam, Kaptan-ı Derya, Yeniçeri Ağası) -> Devşirme veya Türk olabilir.\n• **Kalemiye** (Defterdar, Nişancı, Reisülküttap) -> Devşirme veya Türk olabilir.\n• **İlmiye** (Şeyhülislam, Kazasker, Kadı, Müderris) -> **KESİNLİKLE MEDRESE ÇIKIŞLI VE MÜSLÜMAN DOĞUMLU OLMAK ZORUNDADIR!**",
