    "explanation": "✅ DOĞRU CEVAP: A) Bedergâh (veya Kapıya Çıkma)\nOsmanlı Devleti'nde Acemi Ocağı'nda temel dini, Türkçe ve askeri eğitimini başarıyla tamamlayan devşirme gençlerin, Yeniçeri Ocağı'na veya diğer Kapıkulu ocaklarına (Cebeci, Topçu vb.) resmen atanması ve kütüğe kaydedilmesi törenine **\"Bedergâh\"** veya **\"Kapıya Çıkma\"** denir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Mülazamet: Medreseyi bitiren öğrencilerin kadılık veya müderrislik yapabilmek için sıraya girmesi ve stajyer olarak beklemesi sistemidir.\n• C) Mevkuf: Vakfedilen, devredilen ve bir hayır kurumuna tahsis edilen mallar için kullanılan hukuki terimdir.\n• D) Zaim: Zeamet sahibi olan (yıllık geliri 20.000 ile 100.000 akçe arasında olan dirlik sahibi orta düzey memur/asker) kişidir.\n• E) Bed-i Besmele (Âmin Alayı): Osmanlı'da 4-5 yaşına gelen çocukların ilk mektebe (Sıbyan Mektebi) başlarken düzenlenen neşeli ve dualı merasimidir (\"Besmeleye Başlama\").\n\n💡 KPSS HAFIZA KARTI:\nDevşirmenin Yol Haritası:\nHristiyan Aileden Alınma -> Türk Aileye Verilme -> Acemi Ocağı -> **Bedergâh / Kapıya Çıkma** -> Yeniçeri Ocağı (Asker) veya Enderun (Bürokrat).",
