    "explanation": "✅ DOĞRU CEVAP: A) Yalnız I (Anadolu'da Celali İsyanlarının artması)\n1596 Haçova Meydan Muharebesi'nde (III. Mehmet dönemi) Avusturya ordusu karşısında savaş meydanını terk eden tımarlı sipahiler tespit edilmiş ve Sadrazam Sinan Paşa'nın emriyle dirlikleri ellerinden alınmıştır. İşsiz ve topraksız kalan binlerce sipahi Anadolu'ya dönerek devlete isyan etmiş ve **Celali İsyanları**nın çığ gibi büyümesine yol açmıştır (I).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Celali İsyanları: Topraksız kalan sipahilerin, levend ve sekbanların Anadolu'da çıkardığı büyük halk ayaklanmalarıdır (Büyük Kaçgun).\n• II. Şer'i vergilerin kaldırılması: Yanlıştır. Öşür, haraç, cizye gibi şer'i vergiler dine dayandığı için asla kaldırılamaz; aksine savaş giderleri için olağanüstü vergiler (Avarız) artırılmıştır.\n• III. Yeniçeri Ocağı'nın kaldırılması: Yanlıştır. Yeniçeri Ocağı 1596'da değil, 1826'da II. Mahmut tarafından kaldırılmıştır (Vaka-i Hayriye).\n\n💡 KPSS HAFIZA KARTI:\n1596 Haçova Meydan Muharebesi: III. Mehmet \"Eğri Fatihi\" unvanını almış; ordudan kaçanların cezalandırılması ise Anadolu'da Celali İsyanları'nı patlatmıştır.",
