    "topic": "Osmanlı Kültür ve Medeniyeti (Tımar Sistemi ve Taşra Teşkilatı)",
    "questionText": "Osmanlı Devleti'nde, tımarlı sipahiler taşradaki düzenden sorumlu tutulmuştur. 'Sahib-i arz' olarak nitelendirilen tımarlı sipahiler, kendilerine bırakılan arazinin mülkiyetine sahip değildir. Sipahiler kanuna karşı gelenleri tutuklama yetkisine sahiptir. Tımarlarının olduğu bölgede oturan sipahiler, savaş halinde yetiştirdikleri askerlerle orduya katılmıştır.\nBu bilgilere göre sipahiler hakkında aşağıdakilerden hangisine ulaşılamaz?",
    "options": {
      "A": "Devlet otoritesini temsil ettiklerine",
      "B": "Askeri görevlerinin bulunduğuna",
      "C": "Savaşçıların eğitiminden sorumlu olduklarına",
      "D": "Şer'i hukuku uyguladıklarına",
      "E": "Özel mülkiyet haklarının kısıtlı olduğuna"
    },
    "markedAnswer": "C",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Şer'i hukuku uyguladıklarına\nTımarlı Sipahiler askeri ve idari görevlilerdir; suçluları yakalama ve güvenlik sağlama (zabıt) yetkileri vardır ancak **YARGI (HUKUK) UYGULAMA YETKİLERİ ASLA YOKTUR**. Osmanlı'da yargı yetkisi ve davalara bakma görevi yalnızca ve bağımsız olarak **Kadı**lara aittir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Devlet otoritesini temsil etme: Taşrada asayişi korur, devletin emirlerini uygular.\n• B) Askeri görevler: Savaş zamanında yetiştirdiği cebelülerle birlikte sancak beyinin bayrağı altında orduya katılır.\n• C) Savaşçıların eğitimi: Barış zamanında cebelü askerlerine talim yaptırır.\n• E) Özel mülkiyet haklarının kısıtlı olması: Tımar arazisi devletin (Miri) toprağıdır; sipahi toprağı satamaz, devredemez, miras bırakamaz.\n\n💡 KPSS HAFIZA KARTI:\nTaşrada Görev Dağılımı:\n• Güvenlik ve Askerlik = Tımarlı Sipahi ve Subaşı\n• Adalet, Yargı ve Nikah/Hukuk = Kadı\n• Din ve İbadet = İmam",
