    "topic": "Osmanlı Kültür ve Medeniyeti (Ekonomik Anlayış ve Temel İlkeler)",
    "questionText": "Osmanlı ekonomisindeki temel ilkelerden birisine göre; ülke sınırları içinde mal ve hizmet arzının mümkün olduğunca bol, ucuz ve kaliteli olması amaçlanmıştır.\nOsmanlı Devleti'nde ekonomik hayatı düzenleyen bu ilke aşağıdakilerden hangisidir?",
    "options": {
      "A": "Gelenekçilik",
      "B": "Fiskalizm",
      "C": "Liberalizm",
      "D": "Merkantilizm",
      "E": "İaşecilik"
    },
    "markedAnswer": "B",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) İaşecilik (Provizyonizm)\nOsmanlı klasik ekonomi felsefesinde; ülke sınırları içinde tüketiciyi (halkı) korumak amacıyla piyasada mal, gıda ve hizmetlerin **mümkün olduğu kadar bol, kaliteli ve ucuz** bir şekilde bulundurulması ilkesine **İaşecilik (Provizyonizm)** denir. Bu amaçla gerektiğinde ihracat kısıtlanmış (yasaklanmış), ithalat ise kolaylaştırılmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Gelenekçilik: Ekonomik dengeleri korumak, geçmişten gelen kuralları ve üretim standartlarını değiştirmeden sürdürme eğilimidir.\n• B) Fiskalizm (Hazinecilik): Devlet hazinesinin gelirlerini en üst seviyeye çıkarmayı ve giderleri asgari düzeyde tutmayı hedefleyen maliye ilkesidir.\n• C) Liberalizm: Devlet müdahalesinin olmadığı, serbest piyasa ve özel sermaye odaklı Batı iktisat modelidir.\n• D) Merkantilizm: Bir devletin zenginliğini sahip olduğu altın ve gümüş (değerli maden) miktarıyla ölçen ve ihracatı destekleyen Avrupa iktisat modelidir.\n\n💡 KPSS HAFIZA KARTI:\nOsmanlı Ekonomisinin 3 Temel İlkesi:\n1. **İaşecilik** = Piyasada malın bol, ucuz ve kaliteli olması\n2. **Fiskalizm** = Hazine gelirlerini maksimize etmek\n3. **Gelenekçilik** = Sosyo-ekonomik dengeleri ve eski düzeni muhafaza etmek",
