    "category": "Osmanlı Devleti — Duraklama, Gerileme ve Islahatlar (XVII-XVIII. Yüzyıl)",
    "topic": "İlk Türk İslam Devletleri / Hukuk Sistemi",
    "questionText": "Selçuklu Devletlerinde kadıların başına ----denilir ve sultan tarafından tayin edilirdi. Örfi hukuk sisteminde davalara ----bakardı.\n\nMetindeki boşluklara sırasıyla getirilmesi gereken kavramlar aşağıdaki seçeneklerden hangisinde doğru verilmiştir?",
    "options": {
      "A": "Kadiü’l-kudat / Emir-i Dad",
      "B": "Emir-i Arz / Müşrif-i Memalik",
      "C": "Sahib-i Şurta / Muhtesip",
      "D": "Emir-i dad / Müşrif-i Memalik",
      "E": "Kadiü’l kudat / Sahib-i Şurta"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Kadiü’l-kudat / Emir-i Dad\nSelçuklu devletlerinde (Büyük Selçuklu ve Anadolu Selçukluları):\n1. İslam dinine ve şeriata dayalı davalara bakan kadıların amiri ve şer'i yargı başkanı: **Kadiü'l-Kudat**tır.\n2. Türk geleneklerine (töreye), devlet güvenliğine ve idari suçlara bakan örfi yargı başkanı: **Emir-i Dad**dır (Adalet Emiri). Hatta vezirleri bile yargılama yetkisi vardır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• Emir-i Dad: Örfi hukukun başıdır; sarayda yargılamaları yönetir.\n• Kadiü'l-kudat: Şer'i hukukun başıdır; başkentte oturur, kadıları atar.\n• Sahib-i Şurta: Emniyet müdürü ve şehir güvenlik teşkilatının başıdır.\n• Emir-i Arz: Askeri işlerden ve ordunun ihtiyaçlarından sorumlu divan başkanıdır.\n• Müşrif-i Memalik: Mali ve idari teftiş başkanıdır (Divan-ı İşraf başkanı).\n\n💡 KPSS HAFIZA KARTI:\nSelçuklu Hukuk Sistemi:\n• Şer'i Hukuk Başkanı = Kadiü'l-kudat\n• Örfi Hukuk Başkanı = Emir-i Dad\n• Askeri Davalar = Kazasker (Kadıasker)",
    "isMapQuestion": false,
    "file": "20260904_235415.jpg"
