    "category": "Osmanlı Devleti — Duraklama, Gerileme ve Islahatlar (XVII-XVIII. Yüzyıl)",
    "topic": "Osmanlı Devleti / Hukuk Sistemi ve Mahkemeler",
    "questionText": "Osmanlı Devleti’nde gayrimüslimlerin davalarına cemaat mahkemeleri, yabancılar arasındaki anlaşmazlıklara konsolosluk mahkemeleri, Müslümanların davalarına da şeri mahkemeler bakıyordu.\n\nBuna göre Osmanlı Devleti ile ilgili;\n\nI. laik hukuk kurallarına yer verilmediği,\nII. hukuk birliğinin bulunmadığı,\nIII. hukukta Batılılaşma hareketlerinin görüldüğü\n\nyargılarından hangileri ileri sürülebilir?",
    "options": {
      "A": "Yalnız I",
      "B": "Yalnız II",
      "C": "Yalnız III",
      "D": "I ve II",
      "E": "I, II ve III"
    },
    "markedAnswer": "D",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Yalnız II (Hukuk birliğinin bulunmadığı)\nOsmanlı'da Müslümanların davalarına Şer'i mahkemeler, Gayrimüslimlerin davalarına kendi cemaat mahkemeleri, Avrupalı yabancıların davalarına ise Konsolosluk mahkemelerinin bakması; **imparatorlukta tek bir hukuk düzeninin ve mahkeme birliğinin bulunmadığını** gösterir (Yalnız II). Bu durum laiklik uygulandığı (I) anlamına gelmez (çünkü hepsi dine dayalıdır); merkezi otoriteyi ise güçlendirmez, tam tersine zayıflatır (III).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Laik hukuk: Yanlıştır; Şer'i mahkemeler İslami fıkha, cemaat mahkemeleri Hristiyan/Musevi dini hukukuna dayanır.\n• II. Hukuk birliğinin olmaması: Doğrudur; bir devlette tek bir yasa ve tek tip mahkeme yoksa orada hukuk birliği yoktur.\n• III. Merkezi otoritenin güçlenmesi: Yanlıştır; konsolosluk ve cemaat mahkemeleri Batılı devletlerin Osmanlı'ya müdahale kozu olmuştur.\n\n💡 KPSS HAFIZA KARTI:\nOsmanlı'daki Mahkeme Çeşitleri:\n1. Şer'i Mahkemeler (Müslümanlar ve genel kamu)\n2. Cemaat Mahkemeleri (Gayrimüslim azınlıklar)\n3. Konsolosluk Mahkemeleri (Kapitülasyon sahibi yabancılar)\n4. Ticaret ve Nizamiye Mahkemeleri (Tanzimat'la kurulan karma mahkemeler).",
