    "category": "Osmanlı Devleti — Duraklama, Gerileme ve Islahatlar (XVII-XVIII. Yüzyıl)",
    "topic": "Osmanlı Tarihi / Dağılma Dönemi (Şark Meselesi)",
    "questionText": "İlk kez 1815 Viyana Kongresi'nde Rus Çarı I. Aleksandr tarafından ortaya atılan \"Şark Meselesi\" (Doğu Sorunu), Osmanlı Devleti'nin topraklarının Avrupalı devletlerce paylaşılması projesidir.\nAşağıdakilerden hangisi bu süreçte Osmanlı Devleti'nin aleyhine gelişen olaylardan biri değildir?",
    "options": {
      "A": "Hünkar İskelesi Antlaşması",
      "B": "Kırım Savaşı",
      "C": "Navarin Olayı",
      "D": "Berlin Antlaşması",
      "E": "Küçük Kaynarca Antlaşması"
    },
    "markedAnswer": "A",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Küçük Kaynarca Antlaşması (1774)\n\"Şark Meselesi\" (Doğu Sorunu) terimi ilk kez **1815 Viyana Kongresi'nde** Rus Çarı I. Aleksandr tarafından kullanılmıştır. Küçük Kaynarca Antlaşması ise bu tarihten tam 41 yıl önce, **1774 yılında** imzalanmıştır. Dolayısıyla 1815'te başlayan Şark Meselesi diplomatik sürecine dahil olamaz.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Hünkar İskelesi Antlaşması (1833): Mısır meselesi yüzünden Rusya ile imzalanmış, Boğazlar sorununu başlatan ve Şark Meselesi'ni alevlendiren antlaşmadır.\n• B) Kırım Savaşı (1853-1856): Rusya'nın \"Hasta Adam\" dediği Osmanlı'yı paylaşmak istemesi ve kutsal yerler krizini bahane etmesiyle çıkan büyük Şark Meselesi savaşıdır.\n• C) Navarin Olayı (1827): Yunan isyanını destekleyen İngiliz, Fransız ve Rus donanmalarının Osmanlı donanmasını yaktığı Şark Meselesi darbesidir.\n• D) Berlin Antlaşması (1878): Sırbistan, Karadağ ve Romanya'nın bağımsız olduğu, Kars-Ardahan-Batum'un Rusya'ya geçtiği Şark Meselesi'nin en yıkıcı zirvesidir.\n\n💡 KPSS HAFIZA KARTI:\nŞark Meselesi (Doğu Sorunu):\n• İlk kez telaffuz eden: Rus Çarı I. Aleksandr (1815 Viyana Kongresi).\n• Avrupalıların Planı:\n  - 1. Aşama: Türkleri Balkanlar'dan atmak.\n  - 2. Aşama: Türkleri Anadolu'dan ve İstanbul'dan sürüp Orta Asya'ya hapsetmek.",
