    "topic": "Kurtuluş Savaşı Hazırlık Dönemi (Milli Varlığa Düşman Cemiyetler)",
    "questionText": "İngiltere'nin desteğini sağlayan, halkın dinî duygularını istismar ederek hilafet ve saltanatın korunması amacıyla kurulan millî varlığa düşman cemiyet aşağıdakilerden hangisidir?",
    "options": {
      "A": "Teali-i İslam Cemiyeti",
      "B": "Wilson Prensipleri Cemiyeti",
      "C": "Mavri Mira Cemiyeti",
      "D": "Alyans İsrailit Cemiyeti",
      "E": "Hürriyet ve İtilaf Fırkası"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Teali-i İslam Cemiyeti\nMilli Mücadele Dönemi'nde İstanbul'da medrese hocaları ve ulema tarafından kurulan, İngiliz Muhipleri Cemiyeti ile paralel çalışan; halkın dini hassasiyetlerini istismar ederek \"kurtuluşun ancak padişah ve halifenin emirlerine sıkı sıkıya bağlı kalmakla mümkün olacağını\" savunan ve Mustafa Kemal ile Kuvayımilliye aleyhine fetvalar dağıtan milli varlığa düşman cemiyet **Teali-i İslam Cemiyeti**dir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Wilson Prensipleri Cemiyeti: Halide Edip, Ahmet Emin gibi aydınların Amerikan mandasını tek kurtuluş gördükleri cemiyettir (Sivas Kongresi'nde manda kesin reddedilince fesholmuştur).\n• C) Mavri Mira Cemiyeti: Fener Rum Patrikhanesi'nce kurulan, Megali İdea'yı (Büyük Yunanistan) gerçekleştirmeyi hedefleyen zararlı azınlık cemiyetidir.\n• D) Alyans İsrailit Cemiyeti: Yahudilerin Filistin'de devlet kurmasını ve Osmanlı'daki ticari ayrıcalıklarını korumasını amaçlayan Musevi cemiyetidir.\n• E) Hürriyet ve İtilaf Fırkası: İttihat ve Terakki karşıtı olup Milli Mücadele'ye ve Ankara hükümetine sert muhalefet eden siyasi partidir.\n\n💡 KPSS HAFIZA KARTI:\nMilli Varlığa Düşman (Müslümanların Kurduğu) Cemiyetler:\n• Teali-i İslam (Halifeci)\n• Kürt Teali (Ayrılıkçı)\n• Sulh ve Selamet-i Osmaniye (Saltanatçı)\n• İngiliz Muhipleri (İngiliz mandası)\n• Wilson Prensipleri (ABD mandası)\n• Hürriyet ve İtilaf Fırkası",
    "isMapQuestion": false,
