    "questionText": "3 Mart 1924'te kabul edilen Tevhid-i Tedrisat Kanunu ile;\n\nI. Millet Mektepleri,\nII. İmam Hatip Liseleri,\nIII. İlahiyat Fakülteleri\n\ngibi eğitim kurumlarından hangilerinin açılması istenilmiştir?",
    "options": {
      "A": "Yalnız I",
      "B": "I ve II",
      "C": "I ve III",
      "D": "II ve III",
      "E": "I, II ve III"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) II ve III (İmam Hatip Liseleri ve İlahiyat Fakültesi)\n3 Mart 1924 tarihli **Tevhid-i Tedrisat Kanunu (Öğretim Birliği Kanunu)** medreseleri kapatıp tüm eğitim kurumlarını Maarif Vekaleti'ne (Milli Eğitim Bakanlığı'na) bağlarken; toplumun yüksek dini ihtiyaçlarını ve din görevlilerini bilimsel esaslara göre karşılamak amacıyla Kanun'un 4. maddesi gereğince:\n• II. İmam ve Hatip mektepleri (İmam Hatip Liseleri) açılmıştır.\n• III. Darülfünun bünyesinde İlahiyat Fakültesi kurulması hükme bağlanmıştır.\nMillet Mektepleri (I) ise Tevhid-i Tedrisat ile değil; 1928 yılında Yeni Türk Harflerinin kabulünden sonra halka okuma-yazma öğretmek amacıyla açılmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Millet Mektepleri (1928): Harf İnkılabı'nın ardından 16-45 yaş arası vatandaşlara okuma-yazma öğretmek için açılmıştır; Atatürk 24 Kasım 1928'de \"Başöğretmen\" unvanını almıştır.\n• II. İmam Hatip Mektepleri: Medreselerin kapatılması üzerine din adamı ihtiyacını modern müfredatla yetiştirmek üzere açılmıştır.\n• III. İlahiyat Fakültesi: Yüksek İslam uzmanı ve akademisyen yetiştirmek amacıyla İstanbul Darülfünunu bünyesinde kurulmuştur.\n\n💡 KPSS HAFIZA KARTI:\n3 Mart 1924 Devrimleri Paketi:\n1. Halifeliğin kaldırılması\n2. Tevhid-i Tedrisat Kanunu\n3. Şer'iye ve Evkaf Vekaleti'nin kaldırılması (Diyanet ve Vakıflar kuruldu)\n4. Erkan-ı Harbiye Vekaleti'nin kaldırılması (Ordu siyasetten ayrıldı)\n5. Osmanlı Hanedanı'nın yurt dışına çıkarılması.",
    "isMapQuestion": false,
    "file": "20260904_235637.jpg"
