    "explanation": "✅ DOĞRU CEVAP: B) Halâskâr-ı Zâbitân (Kurtarıcı Subaylar)\n1912 yılında İttihat ve Terakki Cemiyeti'nin baskıcı yönetimine ve meclisteki \"sopalı seçimler\"e tepki göstererek Osmanlı ordusu içinde kurulan silahlı muhalif subaylar grubuna **\"Halâskâr-ı Zâbitân\" (Kurtarıcı Subaylar)** denir. Yayınladıkları muhtıra ile İttihatçı Sait Paşa hükümetini istifaya zorlamış ve Gazi Ahmet Muhtar Paşa'nın \"Büyük Kabine\"sini kurdurmuşlardır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Mim Mim Grubu (M.M.): Milli Mücadele döneminde İstanbul'dan Anadolu'ya gizlice silah, cephane ve istihbarat kaçıran gizli teşkilattır.\n• C) Millî Birlik Komitesi: 27 Mayıs 1960 askeri darbesini gerçekleştiren subaylar heyetidir.\n• D) Sekban-ı Cedit: 1808'de Alemdar Mustafa Paşa tarafından Nizam-ı Cedid'in yerine kurulan kısa ömürlü askeri ocaktır.\n• E) Bostancı Tüfekleri: Osmanlı sarayını ve sahillerini koruyan Bostancı Ocağı tüfekçileridir.\n\n💡 KPSS HAFIZA KARTI:\n1912 Kurtarıcı Subaylar (Halaskar-ı Zabitan) darbesi üzerine İttihatçılar iktidardan düşmüş; ancak Balkan Savaşı hezimetini fırsat bilerek 1913'te ünlü **Bâbıâli Baskını** ile Enver Paşa öncülüğünde mutlak iktidarı ele geçirmişlerdir.",
