    "questionText": "11. Osmanlı Devleti'nin toprak bütünlüğünü savunan İngiltere, XIX. yüzyılın son çeyreğinden itibaren bu politikasından vazgeçmiştir. İngiltere'nin bu şekilde politika değişikliği yapmasında aşağıdakilerden hangisi daha etkili olmuştur?",
    "options": {
      "A": "Üçlü İtilaf Devletlerinin kurulması",
      "B": "Osmanlı'nın Almanya'yla yakınlaşması",
      "C": "İtalya'nın siyasi birliğini sağlaması",
      "D": "Metternich sisteminin ortaya atılması",
      "E": "Osmanlı'nın ıslahatlara hız vermesi"
    },
    "markedAnswer": "A",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Osmanlı'nın Almanya'yla yakınlaşması (ve Reval Görüşmeleri)\nİngiltere XIX. yüzyıl boyunca Rusya'nın Akdeniz'e inmesini engellemek için Osmanlı'nın toprak bütünlüğünü savunmuştur. Ancak 1878 Berlin Antlaşması sonrasında II. Abdülhamit'in Almanya ile yakınlaşması (Bağdat Demiryolu projesi vb.) ve 1908 **Reval Görüşmeleri**'nde İngiltere ile Rusya'nın anlaşması üzerine İngiltere geleneksel Osmanlı politikasını terk etmiş, Osmanlı topraklarını parçalama ve paylaşma yoluna gitmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Üçlü İtilaf'ın kurulması: 1907'de tamamlanmıştır; bu yakınlaşmanın bir sonucudur.\n• C) İtalya'nın birliğini sağlaması: 1870'te gerçekleşmiş, Trablusgarp'ı işgal etmiştir.\n• D) Metternich sistemi: 1815 Viyana Kongresi'nde milliyetçilik hareketlerini bastırmak için kurulmuştur (1878'den çok öncedir).\n• E) Islahatlara hız verilmesi: Osmanlı'nın iç meselesidir; İngiltere'nin tutum değişikliğine neden olmamıştır.\n\n💡 KPSS HAFIZA KARTI:\nİngiltere'nin Politika Dönüm Noktası:\n• 1791 - 1878: Osmanlı toprak bütünlüğünü koruma (Rusya'yı durdurma amaçlı).\n• 1878 sonrası: Osmanlı'yı parçalama politikası (1878 Kıbrıs işgali, 1882 Mısır işgali).",
