      "B": "I: Anayasanın ilan edilmesi / II: Meşrutiyet rejimine geçilmesi",
      "C": "I: Milliyetçilik fikrinin yayılması / II: 31 Mart Olayı'nın meydana gelmesi",
      "D": "I: Tanzimat Fermanı'nın ilan edilmesi / II: Hukukun üstünlüğü ve eşitlik ilkelerinin benimsenmesi",
