    "explanation": "✅ DOĞRU CEVAP: C) I: Milliyetçilik fikrinin yayılması / II: 31 Mart Olayı'nın meydana gelmesi\n31 Mart Olayı bir azınlık veya milliyetçilik isyanı DEĞİLDİR! Derviş Vahdeti'nin İttihad-ı Muhammedi fırkası ve Volkan gazetesi öncülüğünde şeriat talebiyle meşrutiyeti ve meclisi devirmek için çıkarılan gerici (irticai) bir ayaklanmadır. Dolayısıyla Fransız İhtilali'nin yaydığı milliyetçilik akımıyla hiçbir sebep-sonuç ilişkisi yoktur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Islahat Fermanı -> Gayrimüslimlere cizyenin kalkması, devlet memuru olabilme, il meclislerine girme gibi geniş haklar vermiştir (Doğru).\n• B) Anayasanın ilanı (Kanun-u Esasi) -> Osmanlı'da Meşrutiyet rejimine geçilmesini sağlamıştır (Doğru).\n• D) Tanzimat Fermanı -> Padişahın yetkilerini sınırlandırarak kanun üstünlüğünü getirmiştir (Doğru).\n• E) Yeniçeri Ocağı'nın kaldırılması (Vaka-i Hayriye) -> Padişahın ve merkezi devlet otoritesinin güçlenmesini sağlamıştır (Doğru).\n\n💡 KPSS HAFIZA KARTI:\n31 Mart İsyanını Kışkırtan Unsurlar:\n• Derviş Vahdeti (Volkan Gazetesi - İttihad-ı Muhammedi)\n• Hasan Fehmi (Serbesti Gazetesi - İlk basın şehidi)\n• Ahrar Fırkası ve Avcı Taburları (Yeni Meşrutiyet rejimi muhalifleri).",
