    "topic": "I. Dünya Savaşı",
    "questionText": "I. Dünya Savaşı esnasında Osmanlı ile Almanya devletleri arasında kara bağlantısının kurulmasında;\nI. Rusya'nın I. Dünya Savaşı'nı terk etmesi,\nII. Irak Cephesi'nde Osmanlı Devleti'nin başarılar kazanması,\nIII. Bulgaristan'ın İttifak Devletlerine katılması\ngelişmelerinden hangileri etkili olmuştur?",
    "options": {
      "A": "Yalnız I",
      "B": "Yalnız III",
      "C": "I ve II",
      "D": "I ve III",
      "E": "II ve III"
    },
    "markedAnswer": "D",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Yalnız III (Bulgaristan'ın İttifak safında savaşa girmesi)\nI. Dünya Savaşı'nda Almanya ile Osmanlı Devleti arasında coğrafi olarak Avusturya-Macaristan ve Sırbistan üzerinden bir kara koridoru açılabilmesi için Bulgaristan kilit noktadaydı. Osmanlı ordusunun 1915'te Çanakkale Boğazı'nda kazandığı muhteşem **Çanakkale Zaferi**, İtilaf Devletlerinin yenilebileceğini gösterdi. Bunun üzerine **Bulgaristan Krallığı İttifak Devletleri safında savaşa girmiş** ve böylece Almanya-Avusturya-Bulgaristan-Osmanlı arasında kesintisiz demiryolu ve **KARA BAĞLANTISI SAĞLANMIŞTIR** (Osmanlı Bulgaristan'a jest olarak Dimetoka'yı vermiştir).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Brest-Litovsk Antlaşması (1918): Rusya'nın savaştan çekilip Kafkas topraklarını Osmanlı'ya geri bıraktığı antlaşmadır; kara bağlantısıyla ilgisi yoktur.\n• II. Romanya'nın savaştan çekilmesi: Romanya İtilaf safında girmiş ve ezilmiştir; kara bağlantısının ana unsuru Bulgaristan'dır.\n• III. Bulgaristan'ın savaşa girmesi: Osmanlı'ya Almanya'dan ağır silah, cephane ve teknik yardımın doğrudan trenlerle (Balkan Treni) ulaşmasını sağlamıştır.\n\n💡 KPSS HAFIZA KARTI:\nÇanakkale Zaferi'nin Dünya Tarihine 3 Büyük Etkisi:\n1. I. Dünya Savaşı en az 2 yıl uzamıştır.\n2. Çarlık Rusyası'na yardım gidememiş, Rusya'da 1917 Bolşevik İhtilali patlak vermiş ve Çarlık yıkılmıştır.\n3. Bulgaristan İttifak safında savaşa girerek Osmanlı-Almanya kara bağlantısını kurmuştur.",
    "isMapQuestion": false,
