    "topic": "XX. Yüzyıl Başlarında Osmanlı Devleti / Trablusgarp Savaşı",
    "questionText": "Osmanlı Devleti'yle İtalya arasında imzalanan Ouchy Antlaşması'nda şu hükümler yer almıştır:\n• Trablusgarp ve Bingazi İtalya idaresine bırakılacaktır.\n• Trablusgarp halkı dini bakımdan Osmanlı halifesine bağlı kalacaktır.\nBu hükümler doğrultusunda aşağıdakilerden hangisi savunulamaz?",
    "options": {
      "A": "Osmanlı'nın Kuzey Afrika'daki varlığının son bulduğu",
      "B": "Osmanlı'nın halifelik makamının konumundan yararlanmaya çalıştığı",
      "C": "Osmanlı'nın hâkimiyet sahasının daraldığı",
      "D": "İtalya'nın Üçlü İttifak'a katılarak, İtilaf Devletlerini karşısına aldığı",
      "E": "İtalya'nın Akdeniz'de güç kazandığı"
    },
    "markedAnswer": "A",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) İtalya'nın Üçlü İttifak'a katılarak İtilaf Devletlerini karşısına aldığı\n1912 Uşi (Ouchy) Antlaşması hükümleri incelendiğinde; İtalya zaten 1882'den beri Almanya ve Avusturya ile **\"Üçlü İttifak\"**ın resmi üyesidir! Uşi Antlaşması ile bir ittifaka katılmış değildir. Hatta İtalya, I. Dünya Savaşı patlak verince İttifak grubunu satarak 1915 Londra Gizli Antlaşması ile İtilaf Devletleri safına geçmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Kuzey Afrika varlığının son bulması: Trablusgarp ve Bingazi İtalya'ya verilince Osmanlı'nın Afrika kıtasında hiçbir toprağı kalmamıştır (Doğrudur).\n• B) Halifelik makamından yararlanma: \"Trablusgarp halkı dini bakımdan Osmanlı Halifesine bağlı kalacaktır\" maddesiyle kültürel bağ korunmak istenmiştir (Doğrudur).\n• C) Hakimiyet sahasının daralması: Kuzey Afrika'nın son kalesi elden çıkmıştır (Doğrudur).\n• E) İtalya'nın Akdeniz'de güç kazanması: On İki Ada'nın İtalya'nın geçici yönetimine bırakılması İtalya'yı Ege ve Doğu Akdeniz'de güçlendirmiştir (Doğrudur).\n\n💡 KPSS HAFIZA KARTI:\nKuzey Afrika'da Kaybedilen Toprakların Sıralaması:\n1. Cezayir (1830 - Fransa) - İlk kaybedilen\n2. Tunus (1881 - Fransa)\n3. Mısır (1882 - İngiltere)\n4. Trablusgarp ve Bingazi (1912 - İtalya) - Son kaybedilen.",
    "isMapQuestion": false,
