    "questionText": "13. Osmanlı Devleti I. Balkan Savaşı'nda, Balkan devletlerine mağlup olmuş ve Midye-Enez hattının batısındaki bütün topraklarını kaybetmiştir.\n\nBuna göre Osmanlı Devleti'nin Balkan Savaşlarında başarısız olmasında aşağıdakilerden hangisi etkili olmamıştır?",
    "options": {
      "A": "Savaş öncesi, bölgedeki askerlerin terhis edilmesi",
      "B": "Balkan devletleri arasında kiliseler sorununun çıkması",
      "C": "Savaş sırasında subaylar arasında particilik çekişmelerinin yaşanması",
      "D": "Savaşa hazırlıksız bir şekilde girilmesi",
      "E": "Aynı anda birçok cephede mücadele edilmesi"
    },
    "markedAnswer": "E",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Balkan devletleri arasında kiliseler sorununun çıkması\nBalkan devletleri arasında Kiliseler Sorunu'nun çıkması Osmanlı'nın yenilme sebebi değil; tam tersine Balkan devletlerinin Osmanlı'ya karşı birleşmesini engelleyen bir sorundu! Ancak 1910 yılında İttihat ve Terakki hükümetinin çıkardığı **\"Kiliseler ve Mektepler Kanunu\"** ile Bulgar ve Rum kiliseleri arasındaki ihtilaf çözülmüş; bu durum Balkan devletlerinin (Bulgaristan, Yunanistan, Sırbistan, Karadağ) aralarındaki düşmanlığı bitirip Osmanlı'ya karşı ittifak kurmalarına yol açmıştır. Yani sorun çözüldüğü için Osmanlı yenilmiştir!\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Askerlerin terhis edilmesi: Harbiye Nazırı Nazım Paşa'nın savaş çıkmayacağı öngörüsüyle Rumeli'deki 75 bin tecrübeli askeri savaş öncesi terhis etmesi en büyük hatadır.\n• C) Orduda particilik çekişmesi: Subayların İttihatçı ve Halaskar/İtilafçı olarak ikiye bölünmesi, cephede birbirine yardıma gitmemesine yol açmıştır.\n• D) Hazırlıksız girilmesi: İkmal, levazım ve telsiz haberleşmesi felç olmuştur.\n• E) Çok cephede savaş: Osmanlı aynı anda Trakya, Makedonya, Arnavutluk ve Ege kıyılarında 4 devlete karşı savaşmak zorunda kalmıştır.\n\n💡 KPSS HAFIZA KARTI:\nI. Balkan Savaşı'nda Savaştığımız Devletler (Şifre: **BÜSEK / BAYS**):\n• **B**ulgaristan (En kazançlı çıkan)\n• **Y**unanistan\n• **S**ırbistan\n• **K**aradağ (Savaşı ilk başlatan devlet).",
    "isMapQuestion": false,
