    "topic": "Çağdaş Türk ve Dünya Tarihi / II. Dünya Savaşı",
    "questionText": "II. Dünya Savaşı sırasında toplanan Yalta Konferansı'nda;\nI. Birleşmiş Milletler Güvenlik Konseyi'nde daimi üyelere veto hakkı verilmesi,\nII. Türkiye'nin savaşa girmesi durumunda Birleşmiş Milletler'e kurucu üye olarak kabul edilmesi,\nIII. Almanya'nın dört işgal bölgesine ayrılması\nkararlarından hangileri alınmıştır?",
    "options": {
      "A": "Yalnız I",
      "B": "Yalnız II",
      "C": "I ve II",
      "D": "I ve III",
      "E": "I, II ve III"
    },
    "markedAnswer": "B",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) I ve III\n4-11 Şubat 1945 tarihlerinde Kırım'daki Yalta Konferansı'nda \"Üç Büyükler\" (Roosevelt - ABD, Churchill - İngiltere, Stalin - SSCB) bir araya gelmiş ve şu kararları almıştır:\n• I. Birleşmiş Milletler Güvenlik Konseyi'nde daimi üye olacak 5 devlete (ABD, SSCB, İngiltere, Fransa, Çin - FİRÇA) **VETO HAKKI** verilmesi kabul edilmiştir (I).\n• III. Almanya'nın savaştan sonra 4 ayrı işgal bölgesine (ABD, İngiliz, Fransız ve Sovyet bölgeleri) bölünmesi kararlaştırılmıştır (III).\nAyrıca 1 Mart 1945'e kadar Mihver devletlere (Almanya ve Japonya'ya) savaş ilan eden devletlerin BM'nin kurucu üyesi olabileceği kuralı getirilmiştir (Türkiye bu sayede sembolik savaş ilan etmiştir).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Öncül: BM Güvenlik Konseyi veto hakkı (\"Dünya 5'ten büyüktür\" ilkesine konu olan hak Yalta'da kabul edilmiştir).\n• II. Öncül: Atom bombasının Japonya'ya atılması kararı Yalta'da değil, savaşın son konferansı olan Temmuz 1945 Potsdam Konferansı'nda Truman tarafından alınmıştır.\n• III. Öncül: Almanya'nın ve Berlin'in parçalanarak işgal bölgelerine ayrılması Yalta'da onaylanmıştır.\n\n💡 KPSS HAFIZA KARTI:\nBM Güvenlik Konseyi Daimi Üyeleri (Şifre: **FİRÇA**):\n• **F**ransa\n• **İ**ngiltere\n• **R**usya (SSCB)\n• **Ç**in\n• **A**BD.",
    "isMapQuestion": false,
    "file": "20260905_000410.jpg"
