    "category": "XX. Yüzyıl Başlarında Osmanlı (Trablusgarp, Balkan & I. Dünya Savaşı)",
    "topic": "İnkılap Tarihi (Milli Mücadele Hazırlık Dönemi)",
    "questionText": "I. Dünya Savaşı'nın bitmesinden sonra İstanbul'a gelen Mustafa Kemal, aşağıdakilerden hangisinin İstanbul Hükûmeti'nin başında kalması ve kendisinin de bu hükûmette görev alması için çaba göstermiştir?",
    "options": {
      "A": "Tevfik Paşa",
      "B": "Talat Paşa",
      "C": "Reşat Hikmet Bey",
      "D": "Ahmet İzzet Paşa",
      "E": "İsmet Bey"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Ahmet İzzet Paşa\nMustafa Kemal Paşa, Mondros Ateşkes Antlaşması'nın imzalanmasının hemen ardından Yıldırım Orduları Grubu lağvedilince 13 Kasım 1918'de trenle Adana'dan İstanbul'a (Haydarpaşa Garı'na) gelmiştir. İstanbul Boğazı'nda işgal donanmasını görünce yaveri Cevat Abbas'a meşhur **\"Geldikleri gibi giderler!\"** sözünü söylemiştir. Mustafa Kemal'in İstanbul'a geldiği gün, yakın dostu ve kabinede Harbiye Nazırı olmayı umduğu **Sadrazam Ahmet İzzet Paşa kabinesi istifa etmiş**, yerine İngiliz yanlısı Tevfik Paşa kabinesi kurulmuştur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Tevfik Paşa: Ahmet İzzet Paşa'nın istifası üzerine hükümeti kuran, Mustafa Kemal'in mecliste güvenoyu almasını engellemeye çalıştığı sadrazamdır.\n• B) Talat Paşa: I. Dünya Savaşı'nın İttihatçı sadrazamıdır; Mondros imzalanmadan önce Enver ve Cemal paşalarla birlikte bir Alman denizaltısıyla yurt dışına kaçmıştır.\n• C) Reşat Hikmet Bey: Son Osmanlı Mebusan Meclisi'nin ilk başkanıdır.\n• E) İsmet Bey (İnönü): Mustafa Kemal'in İstanbul Şişli'deki evinde Milli Mücadele planlarını hazırladığı en yakın dava arkadaşıdır.\n\n💡 KPSS HAFIZA KARTI:\nMustafa Kemal'in İstanbul Günleri (13 Kasım 1918 - 16 Mayıs 1919):\n• Fethi Okyar ile birlikte **\"Minber\"** gazetesini çıkardı.\n• Padişah Vahdettin ile Vahdettin Köşkü'nde görüşmeler yaptı.\n• 9. Ordu Müfettişi olarak görevlendirilip Bandırma Vapuru ile Samsun'a hareket etti.",
    "isMapQuestion": false,
    "file": "20260905_000718.jpg"
