    "questionText": "30 Ocak 1943'te, Türkiye ile İngiltere arasında yapılan tarihe \"Sağırlar Diyaloğu\" olarak geçen gelişme aşağıdakilerden hangisidir?",
    "options": {
      "A": "Yalta Konferansı",
      "B": "Casablanca Konferansı",
      "C": "Adana Görüşmesi",
      "D": "Moskova Konferansı",
      "E": "Tahran Konferansı"
    },
    "markedAnswer": "C",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Adana Görüşmesi (30-31 Ocak 1943)\n30-31 Ocak 1943 tarihlerinde Adana'nın Yenice Tren İstasyonu'nda beyaz bir tren vagonunda Türkiye Cumhurbaşkanı İsmet İnönü ile İngiltere Başbakanı Winston Churchill arasında gizlice yapılan zirvedir. Churchill, Türkiye'yi derhal II. Dünya Savaşı'na sokmak istemiş; İsmet İnönü ise işitme zorluğunu da diplomatik bir manevra olarak kullanarak her teklife \"Ordumuzun modern teçhizatı eksik, önce silahları verin\" diyerek oyalama taktiği izlemiştir. Bu zirve tarihe **\"Sağırlar Diyaloğu\"** olarak geçmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Yalta Konferansı (1945): Roosevelt, Churchill ve Stalin arasında Kırım'da toplanan savaş sonrası paylaşım konferansıdır.\n• B) Casablanca Konferansı (1943): Roosevelt ve Churchill'in Mihver devletlere \"kayıtsız şartsız teslim\" şartını getirdikleri zirvedir.\n• D) Moskova Konferansı (1943): Dışişleri bakanlarının bir araya gelip Türkiye'nin savaşa girmesini prensipte kararlaştırdıkları toplantıdır.\n• E) Tahran Konferansı (1943): Roosevelt, Churchill ve Stalin'in Normandiya çıkarmasını kesinleştirdikleri zirvedir.\n\n💡 KPSS HAFIZA KARTI:\nTürkiye'nin II. Dünya Savaşı Zirveleri:\n1. Adana Görüşmesi (Ocak 1943 - İnönü & Churchill / Yenice treni)\n2. I. Kahire Görüşmesi (Kasım 1943 - Numan Menemencioğlu & Eden)\n3. II. Kahire Görüşmesi (Aralık 1943 - İnönü, Churchill, Roosevelt).",
