    "questionText": "29 Ekim 1923 tarihinde Cumhuriyet'in ilanı ile birlikte 1921 Teşkilat-ı Esasiye Kanunu'nun 6 maddesinde yapılan değişiklik metnini birlikte hazırlayan devlet adamları aşağıdakilerden hangisinde doğru olarak verilmiştir?",
    "options": {
      "A": "Mustafa Kemal ile Rauf Orbay",
      "B": "Mustafa Kemal ile Ali Fuat Cebesoy",
      "C": "Mustafa Kemal ile Fevzi Çakmak",
      "D": "Mustafa Kemal ile Kazım Karabekir",
      "E": "Mustafa Kemal ile İsmet İnönü"
    },
    "markedAnswer": "E",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Mustafa Kemal ile İsmet İnönü\n28 Ekim 1923 akşamı Çankaya Köşkü'nde Mustafa Kemal'in meşhur **\"Efendiler, yarın cumhuriyeti ilan edeceğiz!\"** açıklamasının ardından masadaki diğer konuklar ayrılmış; Mustafa Kemal Paşa ile İsmet (İnönü) Paşa baş başa kalarak gece boyunca 1921 Teşkilat-ı Esasiye Kanunu'nun devlet şekli, dini, dili, başkenti ve cumhurbaşkanlığı seçimini düzenleyen 6 maddelik anayasa değişikliği kanun teklifini bizzat kaleme almışlardır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Rauf Orbay: Cumhuriyetin ilanına ve hilafetin kaldırılmasına muhalif kalmış, daha sonra Terakkiperver Cumhuriyet Fırkası'nın genel başkanı olmuştur.\n• B) Ali Fuat Cebesoy: Mustafa Kemal'in sınıf arkadaşı, Batı Cephesi eski komutanı ve Terakkiperver kurucularındandır.\n• C) Fevzi Çakmak: Genelkurmay Başkanı olup orduyu siyasetten uzak tutmuş ve devrimleri desteklemiştir (Türkiye'nin 2. Mareşali).\n• D) Kazım Karabekir: Şark Fatihi olup Cumhuriyet ilan edildiğinde İzmir'de ordu komutanıydı; cumhuriyetin aceleye getirildiğini savunmuştur.\n\n💡 KPSS HAFIZA KARTI:\n29 Ekim 1923 Cumhuriyetin İlanı ile Yapılan Hükümet Değişiklikleri:\n• İlk Cumhurbaşkanı: **Mustafa Kemal Atatürk**\n• İlk Başbakan: **İsmet İnönü**\n• İlk TBMM Başkanı: **Ali Fethi Okyar**",
