    "markedAnswer": "D",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Amasya Tamimi (Genelgesi - 22 Haziran 1919)\n22 Haziran 1919 tarihli Amasya Genelgesi'nin 4. maddesinde: **\"Milletin durumunu gözden geçirmek ve haklarını dünyaya duyurmak için her türlü etki ve denetimden uzak bir ulusal kurulun (ulusal bir heyetin) varlığı zorunludur\"** hükmü yer almıştır. Bu madde, ileride kurulacak olan **Heyet-i Temsiliye'nin (Temsil Heyeti)** ve TBMM'nin kurulması fikrinin tarihte İLK KEZ resmi bir belgede yer almasıdır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Samsun Raporu (22 Mayıs 1919): Mustafa Kemal'in İstanbul'a çektiği, Rumların saldırgan olduğunu ve Türklerin manda istemediğini bildiren ilk kişisel raporudur.\n• C) Havza Genelgesi (28 Mayıs 1919): İşgallere karşı tüm yurtta ilk kez protesto telgrafları çekilmesini ve milli mitingler düzenlenmesini emreden genelgedir.\n• D) Erzurum Kongresi (23 Temmuz 1919): Heyet-i Temsiliye'nin 9 kişilik bölgesel bir heyet olarak ilk kez resmen kurulduğu kongredir.\n• E) Amasya Protokolleri (Görüşmeleri - Ekim 1919): İstanbul Hükümeti'nin Temsil Heyeti'ni ve Milli Mücadele'yi hukuken ilk kez tanıdığı ikili görüşmelerdir.\n\n💡 KPSS HAFIZA KARTI:\nTemsil Heyeti Aşamaları:\n1. Fikren ortaya atılması: **Amasya Genelgesi**\n2. Bölgesel olarak kurulması: **Erzurum Kongresi** (9 kişi / Başkanı Mustafa Kemal)\n3. Ulusal hale getirilmesi ve yetkilerinin tüm yurdu kapsaması: **Sivas Kongresi** (16 kişi)\n4. Görevinin sona ermesi: **23 Nisan 1920 TBMM'nin açılması**.",
