    "category": "Milli Mücadele Hazırlık Dönemi ve I. TBMM Dönemi",
    "topic": "Kurtuluş Savaşı Muharebeler Dönemi",
    "questionText": "Batı Cephesi Komutanı İsmet Paşa'nın yönetiminde Yunanları I. İnönü Savaşı'nda mağlup eden TBMM orduları, içte ve dışta birçok kazanım elde edilmesine ortam hazırlamıştır.\n\nBuna göre aşağıdakilerden hangisi bu kazanımlardan birisi değildir?",
    "options": {
      "A": "Moskova Antlaşması'nın imzalanması",
      "B": "Londra Konferansı'nın toplanması",
      "C": "Gümrü Antlaşması'nın imzalanması",
      "D": "İstiklâl Marşı'nın kabul edilmesi",
      "E": "Teşkilat-ı Esasiye'nin ilan edilmesi"
    },
    "markedAnswer": "E",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Gümrü Antlaşması'nın imzalanması\nGümrü Antlaşması, I. İnönü Savaşı'ndan sonra değil; Kazım Karabekir komutasındaki 15. Kolordunun Doğu Cephesi'nde Ermenileri mağlup etmesi sonucunda **3 Aralık 1920 tarihinde** imzalanmıştır. I. İnönü Savaşı ise **6-10 Ocak 1921'de** (Gümrü'den bir ay sonra) yapılmıştır!\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Moskova Antlaşması (16 Mart 1921): I. İnönü Zaferi'nden sonra Sovyet Rusya ile imzalanmış, TBMM'yi tanıyan ilk büyük Avrupa devleti Rusya olmuştur (Batum Misakımilli'den ilk tavizdir).\n• B) Londra Konferansı (Şubat-Mart 1921): I. İnönü Zaferi sonrası İtilaf Devletleri TBMM'yi hukuken ilk kez resmi bir masaya davet etmiştir.\n• D) İstiklâl Marşı'nın kabulü (12 Mart 1921): I. İnönü Zaferi'nin yarattığı milli coşku ortamında TBMM tarafından milli marş olarak kabul edilmiştir.\n• E) Teşkilat-ı Esasiye Kanunu (20 Ocak 1921): I. İnönü Zaferi'nin hemen ardından ilan edilen Türkiye'nin ilk anayasasıdır.\n\n💡 KPSS HAFIZA KARTI:\nI. İnönü Savaşı Sonuçları Şifresi: **MİLÂT**\n• **M**oskova Antlaşması\n• **İ**stiklal Marşı'nın kabulü\n• **L**ondra Konferansı\n• **Â**fganistan Dostluk Antlaşması (İlk Müslüman devlet)\n• **T**eşkilat-ı Esasiye Kanunu (1921 Anayasası)\nAyrıca İsmet Bey Albaylıktan \"Generalliğe\" yükseltilmiştir.",
    "isMapQuestion": false,
