    "topic": "Atatürk Dönemi İç Politika ve İnkılaplar",
    "questionText": "Millî Mücadele'nin zaferle sonuçlanmasıyla birlikte I. TBMM'nin görev süresi dolmuş 1 Nisan 1923'te seçim kararı alınmıştır. Seçimler sonucunda II. TBMM göreve başlamıştır. Bu meclis 4 yıl süreyle çalışmalarını yürütmüştür.\n\nBuna göre aşağıdaki gelişmelerden hangisi II. TBMM Dönemi'nde meydana gelmemiştir?",
    "options": {
      "A": "Halifelik makamına son verilmesi",
      "B": "Terakkiperver Cumhuriyet Fırkası'nın kurulması",
      "C": "Türk Medeni Kanunu'nun çıkarılması",
      "D": "I. Beş Yıllık Sanayi Planı'nın hazırlanması",
      "E": "Tevhid-i Tedrisat Kanunu'nun ilan edilmesi"
    },
    "markedAnswer": "E",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) I. Beş Yıllık Sanayi Planı'nın hazırlanması\nII. TBMM'nin görev süresi **11 Ağustos 1923 ile 1 Ekim 1927** tarihleri arasındadır. **I. Beş Yıllık Sanayi Planı** ise 1929 Dünya Ekonomik Buhranı'nın etkisiyle **1933 yılında** hazırlanmış ve 1934 yılında **IV. TBMM Dönemi'nde** yürürlüğe girmiştir!\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Halifeliğin kaldırılması (3 Mart 1924): II. TBMM döneminde gerçekleştirilen en büyük laikleşme devrimidir.\n• B) Terakkiperver Cumhuriyet Fırkası (Kasım 1924): II. TBMM döneminde kurulan Türkiye'nin İLK muhalefet partisidir (Kazım Karabekir, Rauf Orbay, Ali Fuat Cebesoy).\n• C) Türk Medeni Kanunu'nun kabulü (17 Şubat 1926): II. TBMM döneminde İsviçre'den uyarlanarak kabul edilen devrim kanunudur.\n• E) Tevhid-i Tedrisat Kanunu (3 Mart 1924): II. TBMM döneminde eğitimde birliği sağlayan kanundur.\n\n💡 KPSS HAFIZA KARTI:\nMeclislerin Temel Karakteri:\n• **I. TBMM (1920 - 1923):** \"SAVAŞÇI VE KURUCU MECLİS\" (Milli Mücadele'yi kazandı, Saltanatı kaldırdı, Lozan'ı imzalattı).\n• **II. TBMM (1923 - 1927):** \"İNKILAPÇI / REFORMCU MECLİS\" (Lozan'ı onayladı, Cumhuriyeti ilan etti, Halifeliği kaldırdı, Medeni Kanun'u kabul etti).",
