    "topic": "Milli Mücadele / I. TBMM Dönemi",
    "questionText": "I. TBMM milletvekillerinin İstiklal Mahkemelerinde görev alması TBMM'nin aşağıdaki yetkilerinden hangisini kullandığına kanıttır?",
    "options": {
      "A": "Yargı",
      "B": "Yürütme",
      "C": "Yasama",
      "D": "Kanun yapma",
      "E": "Temsil"
    },
    "markedAnswer": "D",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Yargı\nTBMM tarafından 18 Eylül 1920 tarihinde çıkarılan Firariler Kanunu kapsamında kurulan İstiklal Mahkemeleri'nin üyeleri ve başkanları, doğrudan **TBMM milletvekilleri arasından meclis oylamasıyla seçilmiştir**. Milletvekillerinin doğrudan mahkeme yargıcı olarak görev yapıp karar vermesi, TBMM'nin olağanüstü koşullarda **YARGI YETKİSİNİ** doğrudan kendi eliyle kullandığının ve **Güçler Birliği** ilkesinin en somut kanıtıdır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Yürütme: Kanunları uygulamaktır (İcra Vekilleri Heyeti / Bakanlar Kurulu yürütür).\n• C & D) Yasama / Kanun yapma: Meclisin yasa ve kanun çıkarmasıdır (Hıyanet-i Vataniye Kanunu'nu çıkarmak yasamadır, sanıkları İstiklal Mahkemesi'nde yargılamak yargıdır).\n• E) Temsil: Milletvekillerinin Türk milletini temsil etme sıfatıdır.\n\n💡 KPSS HAFIZA KARTI:\nİstiklal Mahkemeleri Görev Yerleri ve Zamanları:\n1. İç isyanları bastırma ve asker kaçaklarını önleme (1920-1921)\n2. Tekâlif-i Milliye Emirleri'nin uygulanması (1921)\n3. Şeyh Sait İsyanı ve Takrir-i Sükûn dönemi (1925)\n4. Atatürk'e İzmir Suikastı Girişimi davası (1926 - Son görev yeri).",
