    "questionText": "12 Ocak 1920'de İstanbul'da toplanan son Osmanlı Mebusan Meclisi, 28 Ocak 1920'de, Millî Mücadele'nin programı olarak nitelendirilen Misak-ı Millî Kararlarını kabul etmiştir.\nBuna göre aşağıdaki konulardan hangisi Misak-ı Millî Kararlarında yer almamıştır?",
    "options": {
      "A": "Azınlık hakları",
      "B": "Çanakkale ve İstanbul Boğazları",
      "C": "Ülke sınırları",
      "D": "Halk oylaması",
      "E": "Patrikhane hakları"
    },
    "markedAnswer": "B",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Patrikhane hakları\nSon Osmanlı Mebusan Meclisi tarafından 28 Ocak 1920'de oy birliğiyle kabul edilen **Misak-ı Millî kararları** bağımsızlık, sınırlar, boğazlar, borçlar, azınlık hakları ve kapitülasyonlar gibi egemenlik konularını içerir. **Fener Rum Patrikhanesi'nin hakları veya hukuki durumu Misakımillî metninde kesinlikle yer almaz.**\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Azınlık hakları: Komşu ülkelerdeki Müslüman tebaanın hakları oranında azınlıklara hak verileceği belirtilmiştir (Karşılıklılık / Mütekabiliyet).\n• B) Boğazlar: Güvenlik sağlandığında dünya ticaretine açılacaktır.\n• C) Ülke sınırları: Mondros Mütarekesi imzalandığında fiilen Türk süngülerinin koruduğu hat milli sınırdır.\n• D) Halk oylaması: Batı Trakya, Kars-Ardahan-Batum ve Arap vilayetlerinde halkın serbest oylamasına başvurulması kabul edilmiştir.\n\n💡 KPSS HAFIZA KARTI:\nMisak-ı Millî'nin İlan Edildiği Yer: **Son Osmanlı Mebusan Meclisi (İstanbul - 1920)**.\nBunu hazırlayan grup: Mustafa Kemal'in talimatıyla kurulan **Felah-ı Vatan Grubu** (Başkanı Rauf Orbay).",
