    "questionText": "Millî Mücadele Dönemi'nde gösterdikleri direniş ve kahramanlıklardan dolayı bazı şehirlere o dönemde ve ileriki süreçte İstiklal Madalyası verilmiştir.\nBuna göre aşağıdakilerden hangisi bu şehirlerden birisi değildir?",
    "options": {
      "A": "İnebolu",
      "B": "Antep",
      "C": "Samsun",
      "D": "Urfa",
      "E": "Maraş"
    },
    "markedAnswer": "D",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Samsun\nMilli Mücadele Dönemi'nde gösterilen destansı kahramanlıklardan dolayı TBMM tarafından şehirlere İstiklal Madalyası verilmiştir. Bu madalyalar:\n1. **İnebolu (1924):** Kastamonu İnebolu ilçesine cephane taşımacılığındaki kahramanlığından dolayı (Tek ilçe).\n2. **Maraş (1925):** Fransız işgaline karşı halk direnişiyle şehri kurtarmasından dolayı (1973'te 'Kahraman' unvanı aldı).\n3. **Antep (2008):** Şahin Bey ve Karayılan önderliğindeki savunmasından dolayı (1921'de 'Gazi' unvanı almıştı).\n4. **Urfa (2016):** Ali Saip Bey önderliğinde Fransızları kovmasından dolayı (1984'te 'Şanlı' unvanı aldı).\n**SAMSUN İLİNE İSTİKLAL MADALYASI VERİLMEMİŞTİR!**\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İnebolu: İstiklal Yolu'nun (İnebolu-Kastamonu-Çankırı-Ankara) başlangıç noktasıdır; madalyayı İLK alan yerleşimdir (1924).\n• B) Antep: 1921'de I. TBMM'den İLK unvanı (Gazi) alan şehirdir; madalyasını 2008'de almıştır.\n• D) Urfa: 1984'te \"Şanlı\" unvanını almış, madalyasını 2016'da en son alan şehirdir.\n• E) Maraş: 1925'te şehir olarak madalyayı alan İLK ildir.\n\n💡 KPSS HAFIZA KARTI:\nİstiklal Madalyası Alan Yerler Kronolojisi:\n1. İnebolu (1924 - İlçe)\n2. Maraş (1925)\n3. Antep (2008)\n4. Urfa (2016)",
