    "questionText": "TBMM'nin açılış konuşmasını en yaşlı üye sıfatıyla Sinop Mebusu ---- yapmıştır.\n\nBuna göre metinde boş bırakılan yere aşağıdakilerden hangisi getirilmelidir?",
