    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Şerif Bey (Sinop Mebusu)\n23 Nisan 1920 Cuma günü Hacı Bayram Camii'nde kılınan cuma namazının ardından dualarla açılan I. Türkiye Büyük Millet Meclisi'nin ilk açılış konuşmasını, meclis gelenekleri uyarınca en yaşlı üye (Reis-i Sin) sıfatıyla **Sinop Mebusu Şerif Bey** yapmıştır. Konuşmasında milletin tam bağımsızlığını ve esaretten kurtuluşunu haykırmıştır. Ertesi gün yapılan seçimde Mustafa Kemal Paşa Meclis Başkanı seçilmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Rıfat Börekçi: Ankara Müftüsü olup Milli Mücadele lehine ünlü karşı fetvayı veren ve Türkiye Cumhuriyeti'nin İLK Diyanet İşleri Başkanı olan din adamıdır.\n• C) Fevzi Paşa (Çakmak): I. TBMM'de Genelkurmay Başkanlığı ve İcra Vekilleri Heyeti başkanlığı yapan efsane komutandır.\n• D) Ali Fuat Cebesoy: Geyve Boğazı direnişini örgütleyen ve Batı Cephesi'nin ilk komutanlığını üstlenen generaldir.\n• E) Celalettin Arif: Son Mebusan Meclisi başkanı olup Ankara'ya gelerek I. TBMM'ye katılan hukukçudur.\n\n💡 KPSS HAFIZA KARTI:\nI. TBMM'nin Açılışı:\n• Tarih: 23 Nisan 1920\n• Açılış Konuşmasını Yapan En Yaşlı Üye: **Sinop Mebusu Şerif Bey**\n• Seçilen Asil Meclis Başkanı: **Mustafa Kemal Paşa (24 Nisan 1920)**",
