    "explanation": "✅ DOĞRU CEVAP: C) Manastırlı Hamdi Bey (Ahmet Hamdi Martonaltı)\n16 Mart 1920 sabahı İtilaf Devletleri İngiliz askerleriyle Şehzadebaşı Karakolu'nu basıp İstanbul'u resmen işgal ettiğinde; Sirkeci ve Harbiye telgrafhanesinde canı pahasına görev başında kalan ve mors alfabesiyle tıkır tıkır **işgali dakika dakika Ankara'daki Mustafa Kemal Paşa'ya bildiren kahraman vatansever telgrafçı Manastırlı Hamdi Bey**dir. Kendisine Soyadı Kanunu ile Atatürk tarafından 16 Mart işgaline ithafen **\"Martonaltı\"** soyadı verilmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Osman Hamdi Bey: Kaplumbağa Terbiyecisi tablosunun ressamı, ilk Türk müzecisi ve Sanayi-i Nefise Mektebi'nin kurucusudur.\n• B) Şahin Bey: Antep savunmasında Fransızlara karşı \"Düşman cesedimi çiğnemeden Antep'e giremez\" diyerek köprü başında şehit düşen Kuvayımilliye komutanıdır.\n• D) İbrahim Haydar Efendi: Son dönem Osmanlı bürokratlarındandır.\n• E) Ahmet Hamdi Ongun: Cumhuriyet dönemi siyasetçi ve bürokratıdır.\n\n💡 KPSS HAFIZA KARTI:\nMustafa Kemal'in İstanbul'un İşgali Üzerine Aldığı Karşı Tedbirler:\n1. İstanbul ile tüm resmi haberleşme ve telgraf hatları kesildi.\n2. Geyve ve Ulukışla civarındaki demiryolları tahrip edildi (İngilizlerin Anadolu içlerine trenle sevkiyatını önlemek için).\n3. İstanbul'daki tutuklamalara misilleme olarak Anadolu'daki İtilaf subayları tutuklandı.\n4. Ankara'da olağanüstü yetkilere sahip yeni bir meclisin (TBMM) açılacağı ilan edildi.",
