    "questionText": "Lozan Barış Antlaşması'nda kapitülasyonların kesin olarak kaldırılmasına rağmen bu durumun Türkiye ekonomisine kısa sürede olumlu etki yapmamasının temel sebebi aşağıdakilerden hangisidir?",
    "options": {
      "A": "Dış borçların ödenmesinde güçlük çekilmesi",
      "B": "Gümrük tarifelerinin 5 yıl boyunca artırılamayacağına dair taahhütte bulunulması",
      "C": "Osmanlı Bankası'nın yabancıların elinde bulunması",
      "D": "Kabotaj hakkının yabancı devletlere bırakılması",
      "E": "Düyun-u Umumiye İdaresi'nin varlığını sürdürmesi"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Gümrük tarifelerinin 5 yıl boyunca artırılamayacağına dair taahhütte bulunulması\n24 Temmuz 1923 Lozan Barış Antlaşması ile kapitülasyonlar tamamen kaldırılmış ve Türkiye adli, mali, idari tam bağımsızlığını kazanmıştır. Ancak Avrupalı devletlerin baskısıyla antlaşmaya eklenen \"Ticaret Sözleşmesi\" gereğince; **Türkiye, 1916 yılında uygulanan Osmanlı gümrük tarifelerini 5 yıl boyunca (1924-1929 yılları arasında) değiştirmemeyi ve ithalat vergilerini artırmamayı taahhüt etmiştir**. Bu durum yerli sanayinin ilk beş yıl koruma duvarlarından yoksun kalmasına yol açmıştır (1929'da bu sürenin dolmasıyla Gümrük Koruma Kanunu çıkarılmıştır).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Dış borçların ödenmesi: Osmanlı borçları imparatorluktan ayrılan devletler arasında bölüştürülmüş ve Türk Lirası/Fransız Frangı ile taksitlendirilmiştir.\n• C) Osmanlı Bankası: Banknot basma yetkisi 1930'da Merkez Bankası kurulana kadar Osmanlı Bankası'nda kalmıştır.\n• D) Kabotaj hakkı: 1 Temmuz 1926 Kabotaj Kanunu ile Türk karasularında yük ve yolcu taşıma hakkı yalnızca Türk bayraklı gemilere verilmiştir.\n• E) Düyun-u Umumiye: Lozan ile idari yetkileri sona erdirilmiş, sadece borç tahsilat bürosuna dönüştürülmüştür.\n\n💡 KPSS HAFIZA KARTI:\n1929 Yılı İktisadi Dönüm Noktası:\nLozan'daki 5 yıllık gümrük taahhüdü 1929'da bittiği için Türkiye nihayet yüksek korumacı gümrük tarifesi koyabilmiş ve yerli sanayiyi korumaya başlamıştır.",
    "isMapQuestion": false,
