    "explanation": "✅ DOĞRU CEVAP: E) I, II ve III (Tekâlif-i Milliye Emirleri)\nSakarya Meydan Muharebesi öncesinde ordunun silah, mühimmat, yiyecek, giyecek ve lojistik eksikliklerini karşılamak için Başkomutan Mustafa Kemal Paşa tarafından 7-8 Ağustos 1921'de yayımlanan **Tekâlif-i Milliye Emirleri (Milli Yükümlülük Buyrukları)** doğrultusunda:\n• I. Halkın ve tüccarın elindeki silah, cephane ve mühimmatın 3 gün içinde orduya teslim edilmesi zorunlu kılınmıştır.\n• II. Her ailenin bir kat çamaşır, bir çift çorap ve çarık hazırlayıp komisyona vermesi emredilmiştir.\n• III. Taşıt sahiplerinin her ay ordu için 100 kilometre ücretsiz askeri malzeme ve mühimmat taşıması zorunlu tutulmuştur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• Emirlerin eksiksiz uygulanması ve kaçakların önlenmesi için ilçelerde **Tekâlif-i Milliye Komisyonları** ve bölgede **İstiklal Mahkemeleri** kurulmuştur.\n• Topyekûn seferberliğin tarihteki en muazzam örneğidir.\n• Alınan tüm malların bedeli devletçe kaydedilmiş ve savaştan sonra halka kuruşu kuruşuna geri ödenmiştir.\n\n💡 KPSS HAFIZA KARTI:\nTekâlif-i Milliye Emirleri Hangi Savaşlar İçin Kullanıldı?\n1. Sakarya Meydan Muharebesi (Kısmen yetişti - %40)\n2. Büyük Taarruz (Tamamı kullanıldı ve asıl ordu bu sayede donatıldı).",
    "isMapQuestion": false,
