    "questionText": "- 1921 Ankara Antlaşması’nın imzalanması\n- 1921 Kars Antlaşması’nın imzalanması\n\nVerilen gelişmeler aşağıdaki muharebelerden hangisinin sonuçları arasındadır?",
    "options": {
      "A": "I.İnönü Savaşı",
      "B": "II.İnönü Savaşı",
      "C": "Kütahya - Eskişehir",
      "D": "Sakarya Meydan",
      "E": "Büyük Taarruz"
    },
    "markedAnswer": "B",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Sakarya Meydan Muharebesi (23 Ağustos - 13 Eylül 1921)\nSakarya Zaferi'nin kazanılmasının hemen ardından iki tarihi antlaşma imzalanmıştır:\n1. **1921 Kars Antlaşması (13 Ekim 1921):** Sovyetler kontrolündeki Kafkas Cumhuriyetleri (Azerbaycan, Ermenistan, Gürcistan) ile imzalanmış ve Türkiye'nin **DOĞU SINIRI KESİNLEŞMİŞTİR**.\n2. **1921 Ankara Antlaşması (20 Ekim 1921):** Fransa ile imzalanmış; Fransa TBMM'yi tanıyan İLK İTİLAF DEVLETİ olmuş, Hatay hariç güney sınırımız çizilmiş ve Güney Cephesi resmen kapanmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) I. İnönü Savaşı Sonuçları (MİLÂT): Moskova Antlaşması, İstiklal Marşı, Londra Konferansı, Afganistan Dostluk Antlaşması, Teşkilat-ı Esasiye.\n• B) II. İnönü Savaşı Sonuçları: İtalya Anadolu'dan kademeli olarak çekilmeye başlamış, Fransa Ankara'ya temsilci göndererek barış zemini aramıştır. Mustafa Kemal, İsmet İnönü'ye \"Siz orada yalnız düşmanı değil, milletin makûs talihini de yendiniz\" telgrafını çekmiştir.\n• C) Kütahya-Eskişehir Muharebeleri Sonuçları: Kurtuluş Savaşı'ndaki tek yenilgimizdir. Afyon, Eskişehir ve Kütahya işgal edilmiş, ordu Sakarya'nın doğusuna çekilmiştir. Mustafa Kemal'e Başkomutanlık yetkisi verilmiş ve Tekâlif-i Milliye Emirleri yayımlanmıştır.\n• E) Büyük Taarruz (Başkomutanlık) Sonuçları: Batı Anadolu düşmandan tamamen temizlenmiş, Mudanya Ateşkes Antlaşması imzalanmış ve Lozan'a giden yol açılmıştır.\n\n💡 KPSS HAFIZA KARTI:\nDoğu Sınırı Sıralaması: Gümrü (Ermenistan) -> Moskova (Sovyet Rusya) -> Kars (Kesinleşme). Şifre: **G**azi **M**ustafa **K**emal (**G**ümrü - **M**oskova - **K**ars).",
    "isMapQuestion": false,
