    "questionText": "20. Türkiye Cumhuriyeti, esas hedef olarak belirlediği uygarlaşma yolunda ilerlemek için hukuk sisteminde devrimler gerçekleştirmiştir. Buna göre ilk olarak Osmanlı Devleti'nde hukuk alanında yaşanan ikiliklere son vermek amacıyla toplumun bütün kesimlerine uygulanabilecek çağdaş bir hukuk sistemi oluşturulmak istenmiştir. Buna göre toplumsal hukuk alanındaki ikiliklere son vermek amacıyla; I. Türk Medeni Kanunu'nun çıkarılması, II. şeri mahkemelerin kapatılması, III. Maarif Vekâletinin kurulması devrimlerinden hangileri gerçekleştirilmiştir?",
    "options": {
      "A": "Yalnız I",
      "B": "Yalnız II",
      "C": "I ve II",
      "D": "I ve III",
      "E": "I, II ve III"
    },
    "markedAnswer": "B",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) I ve II (Türk Medeni Kanunu ve Şeriye Mahkemeleri)\nCumhuriyet döneminde hukuk sistemini laikleştirmek ve Osmanlı'dan kalan çok başlı hukuk (şeri, cemaat, konsolosluk) karmaşasına son vermek amacıyla:\n• I. 17 Şubat 1926'da **Türk Medeni Kanunu** kabul edilmiş; din, mezhep farkı gözetmeksizin tüm Türk vatandaşları tek bir medeni hukuka bağlanmıştır.\n• II. 8 Nisan 1924'te çıkarılan Mahkemeler Teşkilatı Kanunu ile **Şeriye Mahkemeleri kapatılmış**, yargıda birlik ve laikleşme sağlanmıştır.\nMaarif Vekâleti (III) ise hukuk alanında değil, Milli Eğitim alanındaki teşkilatlanmadır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Türk Medeni Kanunu: İsviçre'den alınmıştır; aile, miras, evlilik ve borçlar hukukunda çağdaş eşitlik getirmiştir.\n• II. Şeriye Mahkemelerinin Kapatılması: Hukukta birliği ve yargı bağımsızlığını tesis etmiştir.\n• III. Maarif Vekâleti: Milli Eğitim Bakanlığı'dır; Tevhid-i Tedrisat Kanunu ile eğitim kurumlarını bünyesinde toplamıştır.\n\n💡 KPSS HAFIZA KARTI:\nHukukta Birliğin ve Laikliğin 2 Anahtarı:\n1. Şeriye Mahkemelerinin Kapatılması (1924)\n2. Türk Medeni Kanunu'nun Kabulü (1926).",
    "isMapQuestion": false,
