    "topic": "Atatürk İlkeleri",
    "questionText": "“Millet bağımsızlığına bizzat kendisi koruyucu olacak ve onun için de teşkilatını bütün köylere kadar genişletecektir. Artık memleketin başına yeni yeni hanedanlar geçmeyecek, millet hâkimiyeti milletin kendisinde kalacaktır.”\n\nMustafa Kemal Paşa’nın bu sözleri aşağıdaki ilkelerden hangisiyle doğrudan ilgilidir?",
