    "topic": "İnkılap Tarihi / Siyasi Alanda Yapılan İnkılaplar (Halifeliğin Kaldırılması)",
    "questionText": "Aşağıdakilerden hangisi halifeliğin kaldırılma nedenleri arasında gösterilemez?",
    "options": {
      "A": "Halifelik makamının yapılacak inkılapların önündeki en büyük engel olması",
      "B": "Halifelik makamının Cumhuriyet rejimi ve ulus devlet anlayışı ile bağdaşmaması",
      "C": "Devletin laikleşmesinin sağlanmak istenmesi",
      "D": "İnkılaplar ve millî egemenliğin önündeki en büyük engelin ortadan kalkmış olması",
      "E": "Cumhuriyet ile halifeliğin bir arada olamayacağının anlaşılmaması"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) İnkılaplar ve millî egemenliğin önündeki en büyük engelin ortadan kalkmış olması\n\"İnkılaplar ve milli egemenliğin önündeki en büyük engelin ortadan kalkmış olması\" bir sebep değil; **Halifeliğin kaldırılmasının BİR SONUCUDUR**. Soru kökü ise kaldırılmanın sebeplerini (nedenlerini) sormaktadır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Halifeliğin inkılaplar önünde engel olması: Halife Abdülmecit Efendi'nin kendisini devlet başkanı gibi görerek cuma alayları düzenlemesi ve ödenek talep etmesi (Nedendir).\n• B) Ulus devlet anlayışıyla bağdaşmaması: Ümmetçi bir kurumun laik ve Türk milli cumhuriyetiyle çelişmesi (Nedendir).\n• C) Devletin laikleşmesini sağlama arzusu: Din ve devlet işlerini tamamen ayırma hedefi (Nedendir).\n• E) Cumhuriyet ile halifeliğin bir arada olamayacağı: Muhaliflerin halifelik makamını cumhuriyete karşı bir sığınak haline getirmesi (Nedendir).\n\n💡 KPSS HAFIZA KARTI:\n3 Mart 1924'te Halifeliğin Kaldırılmasını Hızlandıran Olay:\nHindistan İsmailiye cemaati liderleri **Ağa Han ve Emir Ali**'nin Başbakan İsmet Paşa'ya yazdığı halifeliğin korunmasını isteyen mektubun, hükümete ulaşmadan önce muhalif gazetelerde (Tanin, İkdam) yayımlanması hükümetin sabrını taşırmıştır.",
    "isMapQuestion": false,
