    "explanation": "✅ DOĞRU CEVAP: E) Bumin Kağan\nI. Göktürk Devleti nin kurucusu olan Bumin Kağan adına dikilmiş herhangi bir anıt veya kitabe günümüze ulaşmamıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) II. Göktürk (Kutluk) Devleti kurucusu Kutluk İlteriş Kağan adına dikilen Nomgon (Şivet Ulan) Yazıtı 2022 yılında Moğolistan da keşfedilmiştir.\n• B) Bilge Kağan Yazıtı, Orhun Abideleri nin en önemli taşlarından biri olup 735 yılında oğlu Tenri Kağan tarafından diktirilmiştir.\n• C) Kül Tigin Yazıtı, Bilge Kağan ın kahraman kardeşi Kül Tigin adına 732 yılında dikilmiş ve metni Yolluğ Tigin tarafından taşa kazınmıştır.\n• D) Vezir Tonyukuk Yazıtı, Türk tarihinin ilk veziri ve tarihçisi Tonyukuk tarafından 720-725 yıllarında bizzat diktirilmiştir.",
