    "explanation": "✅ DOĞRU CEVAP: C) Hacip\nHacip (Hâcibü l-Hüccâb): Saray protokolünü düzenleyen, halk ile divan ve hükümdar arasındaki elçilik ve aracılık işlerini yürüten başmabeyincidir; metinde buna dair bir eylem belirtilmemiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Çaşnigir: Hükümdarın sofrasından ve yemeklerin tadımından/zehir kontrolünden sorumlu saray görevlisidir (Metindeki yemeklerinin tadına bakmış ifadesi).\n• B) Candar: Hükümdarı ve sarayı korumakla görevli muhafız birliğinin komutanıdır (Metindeki hükümdarın muhafızlığını yapmıştır ifadesi).\n• D) Emir-i Şikar: Hükümdarın av törenlerini ve av partilerini organize eden saray görevlisidir (Metindeki av partileri düzenlemiş ifadesi).\n• E) Alemidar: Seferlerde ve törenlerde devletin kutsal bayrağını, sancağını ve tuğlarını taşımakla yükümlü görevlidir (Metindeki sancağını taşımış ifadesi).",
