    "questionText": "Kanuni Sultan Süleyman ın Batı politikasının temelinde, Avrupa da oluşması muhtemel bir Hristiyan birliğinin engellenmesi vardır.\n\nBuna göre Kanuni Sultan Süleyman ın;\nI. Fransa yla kapitülasyon antlaşması imzalanması,\nII. Hint Deniz Seferlerine çıkılması,\nIII. Barbaros Hayrettin Paşa nın donanmanın başına geçirilmesi\nfaaliyetlerinden hangileri Hristiyan birliğinin engellenmesine yöneliktir?",
