    "explanation": "✅ DOĞRU CEVAP: A) Yalnız I\nYalnız I: Fransa ya 1535 te kapitülasyonlar (ahd-i atik) tanınarak Fransa Şarlken in Kutsal Roma-Cermen İmparatorluğu ve Papalık bloğundan koparılmış, Avrupa da Haçlı birliği parçalanmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Yalnız II: Hint Deniz Seferleri Batı Hristiyan birliğini engellemek için değil; Gücerat Müslümanlarına yardım etmek ve Portekizlileri Baharat Yolu ndan uzaklaştırmak amacıyla yapılmıştır.\n• C) Yalnız III: Barbaros Hayrettin Paşa nın Kaptan-ı Derya yapılması Akdeniz deki deniz hakimiyetini ve askeri gücü artırmaya yöneliktir, doğrudan diplomatik ittifak bölme hamlesi değildir.\n• D) I ve II: II. öncül Hint Okyanusu ve Doğu ticaret yolları ile ilgilidir, Hristiyan birliğini parçalamaya yönelik değildir.\n• E) I, II ve III: Her üç öncül Osmanlı faaliyeti olmakla birlikte yalnızca Fransa ya kapitülasyon verilmesi Hristiyan ittifakını bölme amacına hizmet eder.",
