    "questionText": "Mustafa nın matematik dersindeki üstün başarısı ve olgunluğu üzerine matematik öğretmeni Yüzbaşı Mustafa Efendi kendisine: Senin adın da Mustafa, benim adım da Mustafa. Bu böyle olmayacak. Arada bir fark olmalı, bundan sonra senin adın Mustafa Kemal olsun. demiştir.\n\nMustafa Kemal in yaşamında önemli bir dönüm noktası olan bu olay aşağıdaki okullardan hangisinde gerçekleşmiştir?",
