    "explanation": "✅ DOĞRU CEVAP: B) Selanik Askeri Rüştiyesi\nSelanik Askeri Rüştiyesi: Mustafa Kemal in kendi isteğiyle sınavına girip kazandığı askeri ortaokuldur; matematik öğretmeni Yüzbaşı Mustafa Efendi Kemal (olgunluk, yetkinlik) adını burada vermiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Şemsi Efendi Mektebi: Mustafa Kemal in modern eğitim gördüğü ilk ilkokuldur; Kemal ismi burada değil askeri ortaokulda verilmiştir.\n• C) Manastır Askeri İdadisi: Mustafa Kemal in lise öğrenimini tamamladığı, Ömer Naci ile edebiyata, Kolağası Mehmet Tevfik Bey ile tarihe ilgi duyduğu okuldur.\n• D) İstanbul Harp Okulu: Mustafa Kemal in 1902 de Teğmen rütbesiyle mezun olduğu yükseköğretim kurumudur.\n• E) İstanbul Harp Akademisi: Mustafa Kemal in 1905 te Kurmay Yüzbaşı olarak mezun olduğu ve ilk görev yeri olan Şam 5. Ordu ya atandığı okuldur.",
