    "explanation": "✅ DOĞRU CEVAP: D) İtalya\nİtalya: St. Jean de Maurienne Antlaşması ile kendisine vadedilen İzmir ve çevresi, 1919 Paris Barış Konferansı nda İngiltere nin baskısıyla Yunanistan a verilince İtilaf ortaklarıyla arası açılmış; Milli Mücadele boyunca Türk ordusuyla çatışmaktan kaçınmış ve II. İnönü Zaferi sonrası Anadolu dan çekilmeye başlamıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İngiltere, Sevr i zorla kabul ettirmek amacıyla Yunan ordusunu Anadolu içlerine sürmüş ve Ankara Hükümeti ile sonuna kadar mücadele etmiştir.\n• B) Fransa güneyde çatışmalara girmiş, ancak Sakarya Zaferi sonrasında TBMM ile Ankara Antlaşması nı imzalamıştır; başlangıçta gizli antlaşmalar konusunda İtalya kadar müttefikleriyle kırgınlık yaşamamıştır.\n• C) Çarlık Rusyası gizli antlaşmaları yapan taraftır ancak 1917 Bolşevik İhtilali ile savaştan çekilmiş ve gizli antlaşmaları dünyaya ifşa etmiştir.\n• E) Yunanistan, İtilaf Devletleri nin desteğiyle Batı Anadolu yu işgal eden ve Megali İdea hayali peşinde koşan işgalci devlettir.",
