    "explanation": "✅ DOĞRU CEVAP: A) Selahaddin Eyyubi\nSelahaddin Eyyubi: 1187 Hıttin Savaşı ile Kudüs ü Haçlılardan geri alarak Kudüs Fatihi olmuş, Mekke ve Medine ye hürmeten tarihte Hadimü l-Haremeyn unvanını kullanan ilk hükümdar olmuştur (Osmanlı da ise bu unvanı ilk kullanan Yavuz Sultan Selim dir).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Melikşah: Büyük Selçuklu Devleti ne en parlak dönemini yaşatan hükümdardır; Celali Takvimi ni hazırlatmış ve Nizamiye Medreselerini geliştirmiştir.\n• C) Gazneli Mahmut: Hindistan a düzenlediği 17 seferle İslamiyet i yayan ve Abbasi halifesinden Sultan unvanını alan ilk Türk hükümdarıdır.\n• D) Satuk Buğra Han: Karahanlı Devleti nde İslamiyet i resmi din olarak kabul eden ve Abdülkerim adını alan hükümdardır.\n• E) Tuğrul Bey: 1055 Bağdat Seferi ile Abbasi halifesini Şii Büveyhoğulları baskısından kurtararak Doğunun ve Batının Sultanı unvanını almıştır.",
    "isMapQuestion": false,
