    "explanation": "✅ DOĞRU CEVAP: D) Bozoklu Celal İsyanı\nBozoklu Celal İsyanı: 1519 da Yavuz Sultan Selim Dönemi nde Tokat/Bozok civarında çıkmış; bastırılmış olmasına rağmen Osmanlı tarihinde XVII. yüzyılda Anadolu yu kasıp kavuran tüm iç isyanlara Celali İsyanları denmesine esin kaynağı olmuştur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Şeyh Bedreddin İsyanı: Çelebi Mehmet (I. Mehmet) Dönemi nde Fetret Devri sonrasında çıkan ilk dini ve sosyal nitelikli isyandır.\n• B) Şahkulu İsyanı: II. Bayezid Dönemi nde Antalya yöresinde Safevi destekli çıkan Şii kökenli isyandır.\n• C) Canberdi Gazali İsyanı: Kanuni Sultan Süleyman ın tahta geçişi sonrasında Memlük Devleti ni yeniden diriltmek için Şam da çıkan isyandır.\n• E) Ahmet Paşa İsyanı: Kanuni Sultan Süleyman döneminde sadrazamlığa Pargalı İbrahim Paşa nın getirilmesi üzerine Mısır a vali atanan Ahmet Paşa nın çıkardığı isyandır.",
