    "explanation": "✅ DOĞRU CEVAP: A) Neccarlık\nNeccarlık: Osmanlı da ağaç işleme, dülgerlik ve marangozluk sanatını icra eden ustalara Neccar denirdi; II. Abdülhamit usta bir neccardır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Palanduzluk: At, katır ve eşek gibi yük hayvanlarının palan ve semerlerini diken ustalara verilen isimdir.\n• C) Hallaçlık: Yün, pamuk ve keten elyafını yay ve tokmak yardımıyla kabartıp temizleyen zanaatkârlardır.\n• D) Kazazlık: İpek iplik büken, ipek şerit ve ibrişim işleyen geleneksel el sanatı erbabıdır.\n• E) Debbağlık: Hayvan derilerini tabaklayarak işleyen ve dericilikle uğraşan esnaftır (Ahi Evran ın da mesleğidir).",
