    "explanation": "✅ DOĞRU CEVAP: E) Ankara Üniversitesi nin resmen kurulması\nAnkara Üniversitesi 1946 yılında, İsmet İnönü nün cumhurbaşkanlığı döneminde kanunla kurulmuştur (Atatürk döneminde bu üniversitenin çekirdeğini oluşturan Hukuk Mektebi 1925 te, DTCF ise 1935 te açılmıştır).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Devlet Demiryolları Genel Müdürlüğü (TCDD) 1927 yılında Atatürk döneminde kurulmuştur.\n• B) Adana-Mersin Demiryolu 1929 yılında Fransız şirketinden satın alınarak millileştirilmiştir.\n• C) Türk Parasının Kıymetini Koruma Kanunu, 1929 Dünya Ekonomik Buhranı nın etkilerini hafifletmek için 1930 da çıkarılmıştır.\n• D) Alpullu Şeker Fabrikası, 1926 yılında Türkiye nin ilk şeker üreten fabrikası olarak Atatürk döneminde açılmıştır.",
    "isMapQuestion": false,
    "file": "20260919_041046.jpg"
