    "topic": "Cumhuriyet Dönemi İlk Muhalefet Partisi / Terakkiperver Cumhuriyet Fırkası",
    "questionText": "Cumhuriyet Dönemi nin ilk muhalefet partisi olan Terakkiperver Cumhuriyet Fırkası nın parti tüzüğünde;\n• Fırka, efkâr ve itikad-ı diniyyeye (dini inanç ve düşüncelere) hürmetkârdır.\n• Hükümetin vazifeleri asgari hadde indirilmeli ve adem-i merkeziyet (yerinden yönetim) esası tatbik edilmelidir.\nmaddeleri yer almıştır.\n\nBuna göre partinin benimsediği temel siyasi ve idari anlayış aşağıdakilerden hangisinde doğru olarak verilmiştir?",
    "options": {
      "A": "Devletçilik — Sosyalizm",
      "B": "Muhafazakârlık — Âdem-i merkeziyetçilik (Liberalizm)",
      "C": "Devrimcilik — Aşırı merkeziyetçilik",
      "D": "Milliyetçilik — Korporatizm",
      "E": "Laiklik — Jakobenizm"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Muhafazakârlık — Âdem-i merkeziyetçilik (Liberalizm)\nDini inançlara hürmetkâr olmak Muhafazakârlığı; yerinden yönetim ve devlet müdahalesini sınırlamak ise Âdem-i merkeziyetçilik ve Liberalizmi temsil eder.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Devletçilik CHP nin ilkesidir; TCF ekonomide liberalizmi (serbest piyasa ekonomisini) savunmuştur.\n• C) Parti radikal inkılapçılığa karşı tedriciliği ve geleneklere saygıyı savunmuştur, aşırı merkeziyetçi değil yerinden yönetimcidir.\n• D) Parti korporatist değil, bireysel hürriyetleri ve liberal serbest piyasayı esas alan bir fırkadır.\n• E) Partinin dini inanç maddesi laiklik karşıtı unsurların partiye sızmasına yol açmış ve Şeyh Sait İsyanı sonrası kapatılmasına gerekçe gösterilmiştir.",
    "isMapQuestion": false,
    "file": "20260919_041046.jpg"
