    "explanation": "✅ DOĞRU CEVAP: A) Yalnız I\nYalnız I: Berlin Antlaşması nın 61. maddesiyle Osmanlı Devleti nin Ermenilerin yaşadığı vilayetlerde (Vilayet-i Sitte) ıslahat yapması ve bunu büyük devletlere bildirmesi şart koşulmuş, böylece Ermeni Meselesi ilk kez uluslararası bir boyut kazanmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Yalnız II: Sırbistan Berlin Antlaşması ile ıslahat yapılacak bir Osmanlı toprağı değil; Romanya ve Karadağ ile birlikte Osmanlı dan ayrılarak tamamen bağımsız bir devlet olmuştur.\n• C) I ve II: Sırplar bağımsızlığını kazandığı için Osmanlı nın onlar için ıslahat yapması söz konusu değildir.\n• D) II ve III: Bulgaristan topraklarında Osmanlı ya bağlı özerk Bulgar Prensliği ve Şarki Rumeli vilayeti kurulmuştur.\n• E) I, II ve III: Yalnızca Ermenilerin yaşadığı yerler ıslahat maddesi kapsamına alınmıştır.",
    "isMapQuestion": false,
    "file": "20260919_041049.jpg"
