    "explanation": "✅ DOĞRU CEVAP: D) İttihat ve Terakki Fırkası\nİttihat ve Terakki Fırkası: 1889'da Askeri Tıbbiye öğrencileri (İbrahim Temo, İshak Sükuti, Abdullah Cevdet vb.) tarafından gizli hücreler, parolalar ve yemin törenleriyle İtalyan Carbonari cemiyeti model alınarak kurulmuştur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Hürriyet ve İtilaf Fırkası: 1911'de İttihat ve Terakki'ye muhalif olarak kurulan ve liberal-muhafazakâr anlayışı savunan sivil partidir.\n• B) Fedakâran-ı Millet Cemiyeti: II. Meşrutiyet'in ilanından sonra II. Abdülhamit'in istibdat mağdurları tarafından kurulan cemiyettir.\n• C) Osmanlı Ahrar Fırkası: Prens Sabahattin'in adem-i merkeziyetçilik ve liberal fikirleri doğrultusunda 1908'de kurulan ilk muhalefet partisidir.\n• E) Osmanlı Sosyalist Fırkası: İştirakçi Hilmi önderliğinde 1910'da kurulan ilk sosyalist siyasi partidir.",
