    "questionText": "Milli Mücadele Dönemi'nde Fransız işgal güçlerine ve Ermeni intikam alaylarına karşı; Şahin Bey'in Kilis-Antep yolunda şehit düşene kadar gösterdiği kahramanlık ve Karayılan'ın direnişiyle destanlaşan, TBMM tarafından 1921 yılında 'Gazi' unvanıyla onurlandırılan şehrimiz aşağıdakilerden hangisidir?",
