    "explanation": "✅ DOĞRU CEVAP: C) I ve II\nI ve II: Gümrü (TBMM-Ermenistan) ve Moskova (TBMM-Sovyet Rusya) antlaşmaları iki devlet arasında doğrudan imzalanan ikili diplomatik metinlerdir. Kars Antlaşması ise TBMM ile Azerbaycan, Ermenistan ve Gürcistan'dan oluşan çok taraflı bir antlaşmadır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Gümrü Antlaşması ikilidir ancak Moskova Antlaşması da TBMM ile Rusya arasında ikili bir antlaşmadır.\n• B) Moskova Antlaşması ikilidir ancak Gümrü Antlaşması da iki devlet arasında yapılmıştır.\n• D) Kars Antlaşması ikili değil çok taraflı bir antlaşmadır.\n• E) Kars Antlaşması çok taraflı olduğu için tüm öncüller ikili sayılamaz.",
