    "explanation": "✅ DOĞRU CEVAP: E) Hacip\nHacip: İslamiyet öncesi Türk devletlerinde değil, Karahanlı, Gazneli ve Büyük Selçuklu gibi TÜRK-İSLAM DEVLETLERİNDE saray protokolünü yöneten başmabeyincidir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Aygucı (Üge): Eski Türklerde hükümdardan sonra gelen vezir / başbakandır; meclise başkanlık edebilir.\n• B) Buyruk: Eski Türk hükümetinde bakan / nazır karşılığı görev yapan devlet ricalidir.\n• C) Tamgacı (Bitikçi): Hakanın mührünü (damga) taşıyan, iç ve dış yazışmaları yürüten katip ve diplomattır.\n• D) Tudun: Eski Türklerde vergi toplamakla ve idari denetimle görevli memur / valiliktir.",
