    "explanation": "✅ DOĞRU CEVAP: C) Büyük Selçuklu Devleti\nBüyük Selçuklu Devleti: 1015'ten itibaren Çağrı Bey ile keşif akınları başlatmış, 1071 Malazgirt Zaferi'nin ardından Sultan Alparslan'ın 'Toprak fethedenin malıdır' emriyle Anadolu'nun Türkleşmesini devlet politikası yapmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Karahanlılar: Orta Asya'da (Maveraünnehir, Kaşgar) kurulan ilk Müslüman Türk devletidir; Anadolu fetihleriyle ilgisi yoktur.\n• B) Gazneliler: Horasan ve Hindistan coğrafyasına hükmetmişlerdir; Dandanakan Savaşı'nda Selçuklulara yenilerek Hindistan'a çekilmişlerdir.\n• D) Harzemşahlar: Harezm bölgesinde kurulmuş, 1230 Yassıçemen Savaşı'nda Türkiye Selçuklularına yenilerek yıkılış sürecine girmiştir.\n• E) Tolunoğulları: Mısır'da kurulan ilk Türk-İslam devletidir; Nil vadisi ve Suriye'de hüküm sürmüştür.",
