    "questionText": "Aralık 1979'da Sovyet Sosyalist Cumhuriyetler Birliği'nin (SSCB) Afganistan'ı işgal etmesiyle Soğuk Savaş'ta Yumuşama (Detant) Dönemi fiilen sona ermiş ve gerginlik yeniden tırmanmıştır.\n\nBu gelişmenin uluslararası alandaki sonuçları ile ilgili olarak aşağıdakilerden hangisine ulaşılamaz?",
