    "explanation": "✅ DOĞRU CEVAP: A) Emevilerin uyguladığı Mevali (Arap milliyetçiliği) politikası\nEmevilerin Mevali politikası: Arap olmayan Müslümanları ikinci sınıf (azatlı köle) gören ırkçı bir politika olduğu için Türklerin İslamiyet'e girişini hızlandırmamış, aksine geciktirmiş ve Türgişlerin Emevilerle savaşmasına yol açmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Gök Tanrı inancında tek bir yaratıcıya inanılması, kurban kesilmesi, ruhun ölümsüzlüğü İslam inanç esaslarıyla büyük benzerlik göstermiştir.\n• C) 751 Talas Savaşı'nda Karluk, Yağma ve Çiğil Türkleri Abbasilerin yanında yer alarak Müslüman Arapları yakından tanımış ve İslamiyet'i kabul etmeye başlamıştır.\n• D) Abbasiler Mevali politikasını terk edip Türklere ordu ve yönetimde geniş yer vererek İslamlaşmayı teşvik etmiştir.\n• E) Türklerdeki fetih ve dünyayı adaletle yönetme arzusu, İslamiyet'in cihad ve i'lay-ı kelimetullah mefkuresiyle tam bir uyum sağlamıştır.",
