    "questionText": "II. Mahmut Dönemi'nde Divan-ı Hümayun kaldırılarak yerine Batı tarzı bakanlıklar (Nezaretler) kurulmuştur.\n\nBu kapsamda sadrazamın iç işleri ve mülki idareye dair yardımcılığını yürüten Sadaret Kethüdalığı makamı lağvedilerek yerine aşağıdaki bakanlıklardan hangisi kurulmuştur?",
