    "questionText": "1331 yılında Orhan Gazi tarafından İznik'in fethinden sonra kurulan, Osmanlı Devleti'nin ilk medresesi unvanına sahip İznik Orhaniyesi'ne (İznik Medresesi) tayin edilen ilk Osmanlı müderrisi aşağıdakilerden hangisidir?",
