    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Tahta geçebilecek aday sayısını sınırlandırarak taht kavgalarını azaltmak ve merkezi otoriteyi güçlendirmek\nHanedanın tüm amca, yeğen ve kardeşlerini taht iddiasından çıkarıp yalnız padişah ve oğullarıyla sınırlandırarak taht kavgalarını azaltmak ve merkezi devleti tahkim etmek amaçlanmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Padişah yetkileri meclisle paylaşılmamış; bilakis mutlak merkeziyetçilik tesis edilmiştir.\n• B) Veraset hanedan içi bir kuraldır, gayrimüslim tebaanın idareye katılımı ile ilgisi yoktur.\n• C) I. Murat bizzat Sırpsındığı, Çirmen ve I. Kosova zaferleriyle Balkan fetihlerinin en büyük fatihidir.\n• D) Tımar sistemi güçlendirilmiş, Rumeli Beylerbeyliği kurulmuştur.",
