    "questionText": "Atatürk Dönemi'nde gerçekleştirilen inkılap hareketlerinden hangisinin doğrudan 'Ulusal Egemenliğin (Milli İradenin) Güçlendirilmesine' yönelik olduğu savunulamaz?",
