      "A": "Saltanatın kaldırılması (1 Kasım 1922)",
      "B": "Cumhuriyetin ilan edilmesi (29 Ekim 1923)",
      "C": "Kadınlara milletvekili seçme ve seçilme hakkının tanınması (1934)",
      "D": "Erkan-ı Harbiye Vekaleti'nin kaldırılarak subayların siyasetten ayrılması (1924)",
      "E": "Tevhid-i Tedrisat Kanunu'nun kabulü ve medreselerin kapatılması (1924)"
