    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Yunanistan\nYunanistan: 1946-1949 İç Savaşı'nda Batılıların (Truman Doktrini ve Marshall Planı) desteğiyle komünist gerillaları yenmiş, kapitalist Batı Bloku'nda kalarak 1952'de Türkiye ile birlikte NATO'ya girmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Polonya: Savaş sonrası Kızıl Ordu işgaliyle komünist yönetimin kurulduğu Doğu Bloku ve Varşova Paktı üyesidir.\n• C) Romanya: Sovyet kontrolünde komünist blokta yer almıştır.\n• D) Bulgaristan: Georgi Dimitrov önderliğinde komünist idarenin kurulduğu Balkan ülkesidir.\n• E) Macaristan: 1956'da Sovyet işgaline uğrayan Doğu Bloku ülkesidir.",
    "isMapQuestion": false,
    "file": "20260919_041256.jpg"
