    "questionText": "1992 yılında Sovyetler Birliği'nin dağılmasından sonra Türk Cumhuriyetleri ve akraba topluluklarla ekonomik, ticari, teknik ve kültürel iş birliğini geliştirmek amacıyla kurulan Türk İşbirliği ve Koordinasyon Ajansı Başkanlığı'nın (TİKA) yurt dışında restore ettiği veya inşa ettiği anıtsal projeler arasında;\nI. Moğolistan'da Orhun Müzesi'nin yaptırılması ve Orhun Abideleri'nin koruma altına alınması,\nII. Bosna-Hersek'teki tarihi Mostar Köprüsü'nün aslına uygun olarak yeniden inşası,\nIII. Süveyş Kanalı'nın genişletilmesi ve liman tesislerinin inşası\nfaaliyetlerinden hangileri yer alır?",
