    "explanation": "✅ DOĞRU CEVAP: C) I ve II\nI ve II: TİKA Moğolistan'daki Bilge Kağan ve Kül Tigin anıtlarını müzeye kavuşturmuş, ata yurdu ile bağları güçlendirmiştir. Aynı şekilde savaşta yıkılan Bosna'daki Mimar Hayrettin eseri Mostar Köprüsü'nü ihya etmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Orhun Müzesi TİKA'nın en büyük prestij projelerindendir ancak Mostar Köprüsü de TİKA'nın ortak restorasyon zaferidir.\n• B) Mostar Köprüsü TİKA projesidir ancak Orhun Abideleri projesi de TİKA'nındır.\n• D) Süveyş Kanalı Mısır devletinin kontrolünde uluslararası bir suyoludur; TİKA'nın tarihi miras ve iş birliği kapsamındaki projelerinden değildir.\n• E) Süveyş Kanalı projesi TİKA projesi değildir.",
    "isMapQuestion": false,
