    "explanation": "✅ DOĞRU CEVAP: B) Seydi Ali Reis\nSeydi Ali Reis: IV. Hint Seferi komutanı olup Mir'atü'l-Memalik (ilk seyahatname), Kitabü'l-Muhit (denizcilik rehberi) ve Mir'at-ı Kainat eserlerinin yazarı büyük Türk amiralidir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Piri Reis: Kitab-ı Bahriye'nin ve meşhur ceylan derisi dünya haritalarının müellifidir.\n• C) Murat Reis: II. Hint Seferi komutanı olup Basra Körfezi'nde Portekizlilerle savaşmıştır.\n• D) Salih Reis: Cezayir Beylerbeyi olup Fas ve Kuzey Afrika fetihlerinde rol oynamıştır.\n• E) Kurtoğlu Hızır Reis: Sumatra Seferi'ne (Açe Seferi) çıkan Osmanlı denizcisidir.",
