    "category": "Milli Mücadele Hazırlık Dönemi ve I. TBMM Dönemi",
    "topic": "I. TBMM'ye Karşı Çıkan Ayaklanmalar / Çapanoğlu İsyanı",
    "questionText": "Tarih öğretmeni Aydın dersinde: 'I. TBMM'ye karşı çıkan ayaklanmalardan biri de bölgenin köklü ve nüfuzlu ailelerinden biri olan Çapanoğulları ailesinin öncülüğünde çıkmıştır. Bu isyan Ankara Hükümeti'ni uzun süre meşgul etmiş ve ancak Çerkez Ethem kuvvetlerinin müdahalesiyle bastırılabilmiştir.' bilgisini vermiştir.\n\nBuna göre öğretmenin bahsettiği Çapanoğlu Ayaklanması aşağıdaki şehirlerimizden hangisinde cereyan etmiştir?",
    "options": {
      "A": "Yozgat",
      "B": "Konya",
      "C": "Bolu",
      "D": "Afyon",
      "E": "Düzce"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Yozgat\nYozgat: Çapanoğlu İsyanı (Çapanoğulları Celal, Edip ve Halit beyler) Yozgat ve civarında çıkmış; Ankara'ya çok yakın olması sebebiyle Meclis için büyük tehlike yaratmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Konya: Delibaş Mehmet ve Bozkır isyanlarının merkezidir.\n• C) Bolu: Bolu-Düzce-Hendek isyanları bölgesidir.\n• D) Afyon: Çopur Musa İsyanı'nın çıktığı yerdir.\n• E) Düzce: Marmara-Batı Karadeniz geçiş hattındaki hilafet yanlısı ayaklanma sahasıdır.",
    "isMapQuestion": false,
    "file": "20260919_041329.jpg"
