    "markedAnswer": "E",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Yetkili mercilerce kapatılması\nDerneklerin tüzel kişiliğinin sona ermesi iki yolla olur:\n1. **İnfisah (Kendiliğinden Sona Erme):** Herhangi bir yargı veya idare kararına gerek kalmaksızın kanundaki şartların doğmasıyla tüzel kişiliğin bizzat bitmesidir (Amacın gerçekleşmesi, paranın/yönetimin tükenmesi, genel kurulun toplanamaması vb.).\n2. **Fesih (Kararla Sona Erdirilme):** Bir irade kararıyla kapatılmadır. Derneğin yetkili mahkeme veya idari mercilerce kapatılması bir **FESİH** işlemidir; infisah değildir!\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Amacın gerçekleşmesi: Derneğin kurulma amacı gerçekleştiğinde kendiliğinden sona erer (İnfisah).\n• C) İlk genel kurulun süresinde yapılmaması: İlk 6 ayda genel kurul yapılmazsa kendiliğinden sona erer (İnfisah).\n• D) Borç ödemede acze düşmesi: İflas/aciz halinde kendiliğinden infisah eder.\n• E) Tüzük gereği yönetim kurulunun oluşturulamaması: Organ eksikliği infisah sebebidir.\n\n💡 KPSS HAFIZA KARTI:\nDerneklerin Sona Ermesi:\n• **Fesih:** Genel Kurul kararıyla kapatma veya Mahkeme kararıyla kapatma (Karar şarttır).\n• **İnfisah:** Kendiliğinden bitme (Amaç bitti, para bitti, kurul toplanamadı).\n• Dernek Kurma Şartı: En az **7 gerçek veya tüzel kişi** ile izin almadan kurulur.",
    "isMapQuestion": false,
    "file": "20260904_235902.jpg"
