    "markedAnswer": "B",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Sendika üyeliği\n657 sayılı Devlet Memurları Kanunu'na göre devlet memurlarının hakları ve yasakları birbirinden kesin çizgilerle ayrılmıştır:\n• **MEMURUN HAKLARI:** Güvenlik, çekilme (istifa), izin, müracaat ve şikayet, **SENDİKA KURMA VE SENDİKAYA ÜYE OLMA (4688 sayılı Kanun)**. Memurun sendikaya üye olması anayasal bir HAKTIR.\n• **MEMURUN YASAKLARI:** Toplu eylem yasağı, **GREV YASAĞI**, Ticaret yasağı, Hediye alma yasağı, Siyasi partiye girme ve siyasi faaliyet yasağı, Basına bilgi demeç verme yasağı.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Toplu hareket: Memurların topluca görevi bırakması veya yavaşlatması kesinlikle yasaktır.\n• B) Grev: Memurların grev yapma hakkı kesinlikle yoktur; greve katılmak devlet memurluğundan çıkarma cezası sebebidir.\n• D) Hediye alma: Tarafsızlığı gölgeleyecek hediye ve menfaat sağlama yasaktır.\n• E) Siyasi faaliyette bulunma: Memurlar hiçbir siyasi partiye üye olamaz ve siyasi propaganda yapamaz.\n\n💡 KPSS HAFIZA KARTI:\nMemurun Sendika vs Grev Ayrımı:\n• Sendika Kurma ve Üye Olma = **VAR (Haktır)**.\n• Grev Yapma = **YOKTUR (KESİNLİKLE YASAKTIR)**.\n• Siyasi Partiye Üye Olma = **YOKTUR (YASAKTIR)**.",
