    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Kanun > Cumhurbaşkanlığı Kararnamesi > Yönetmelik\nNormlar hiyerarşisinde üstten alta sıralama: Anayasa > Kanun / Milletlerarası Antlaşmalar > Cumhurbaşkanlığı Kararnamesi > Yönetmelik şeklindedir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Anayasa en üst normdur, CBK kanun ve Anayasa'dan üstün olamaz.\n• C) Anayasa piramidin tepesindedir, kanun Anayasa'dan üstte yer alamaz.\n• D) Cumhurbaşkanlığı Kararnamesi yönetmelikten üsttedir, sıralama terstir.\n• E) Kanun, Cumhurbaşkanlığı Kararnamesinden hiyerarşik olarak daima üstündür.",
