    "explanation": "✅ DOĞRU CEVAP: B) Uluslararası Ceza Divanı (UCD)\n2004 anayasa değişikliği ile vatandaşın suç sebebiyle yabancı ülkeye iadesi yasağına yalnızca Uluslararası Ceza Divanına taraf olmanın getirdiği yükümlülükler istisnası eklenmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) AİHM bireysel hak ihlallerini tazminatla karara bağlar, ceza yargılaması veya kişi iadesi talep etmez.\n• C) Uluslararası Adalet Divanı sadece devletler arasındaki uyuşmazlıklara bakar, kişileri yargılamaz.\n• D) ABAD, Avrupa Birliği hukuku uyuşmazlıklarına bakar ve Türkiye üye değildir.\n• E) BM Uluslararası Hukuk Komisyonu bir yargı organı değil, uluslararası hukuku kodifiye eden kuruldur.",
