    "explanation": "✅ DOĞRU CEVAP: A) En az üçte biri (200 milletvekili)\nAnayasa m. 175 uyarınca Anayasa değişikliği teklifi ancak TBMM üye tamsayısının en az üçte birinin (200 milletvekili) yazılı teklifi ile verilebilir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Beşte bir (120 MV), AYM'ye iptal davası açma veya Meclis soruşturması açılması teklif yeter sayısıdır.\n• C) Salt çoğunluk (301 MV), Meclis soruşturması açılmasına karar verme ve Cumhurbaşkanının geri gönderdiği kanunu aynen kabul sayısıdır.\n• D) Beşte üç (360 MV), anayasa değişikliğinin kabulü ve referanduma sunulması asgari sınırıdır.\n• E) Üçte iki (400 MV), anayasa değişikliğinin referanduma gerek kalmaksızın doğrudan yürürlüğe girebilmesi için aranan kabul sayısıdır.",
    "isMapQuestion": false,
    "file": "20260919_143233.jpg"
