    "explanation": "✅ DOĞRU CEVAP: A) Yalnız I\nSiyasi parti grupları Cumhurbaşkanlığına aday gösterebilir (I); ancak Meclis Başkanlığı için aday gösteremezler (m.94) ve dokunulmazlığın kaldırılması konusunda görüşme yapıp karar alamazlar (m.83).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Yasama dokunulmazlığının kaldırılması konusunda parti gruplarında görüşme yapılması ve karar alınması anayasaca kesinlikle yasaklanmıştır.\n• C) TBMM Başkanlığı tarafsız bir makam olduğu için siyasi parti grupları başkanlık için aday gösteremez.\n• D) II numaralı işlem anayasal yasak kapsamında olduğu için siyasi parti grupları bu yetkiye sahip değildir.\n• E) Hem II hem de III numaralı hususlar anayasal yasaklar kapsamındadır.",
