    "explanation": "✅ DOĞRU CEVAP: D) III ve IV\nBakan seçilenin milletvekilliği kendiliğinden sona erer (III); 1 ayda 5 birleşime özürsüz katılmayanın vekilliği ise Meclis kararıyla düşürülebilir (IV).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Partinin kapatılmasına sebep olma kuralı 2010 anayasa değişikliğiyle yürürlükten kaldırılmıştır.\n• B) Meclis Başkanı seçilen milletvekilinin üyeliği sona ermez; sadece oturumları yönetir ve oy kullanamaz.\n• C) II milletvekilliğini düşürmez, III ise göreve başlama ile doğrudan düşürür.\n• E) I artık vekilliği düşürmemektedir, dolayısıyla doğru seçenek yalnızca III ve IV'tür.",
