    "explanation": "✅ DOĞRU CEVAP: D) 301 (Üye tamsayısının salt çoğunluğu)\n2017 değişikliğiyle Anayasa m. 89 uyarınca Cumhurbaşkanının geri gönderdiği kanunun aynen kabulü için TBMM üye tamsayısının salt çoğunluğu (en az 301 milletvekili) aranır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) 151, TBMM olağan karar yeter sayısının asgari alt sınırıdır.\n• B) 200, Meclisin toplantı yeter sayısıdır (üye tamsayısının 1/3'ü).\n• C) 251, mevzuatta yer almayan bir sayıdır.\n• E) 360, referanduma götürülebilen anayasa değişikliği çoğunluğudur (3/5).",
