    "explanation": "✅ DOĞRU CEVAP: D) II ve III\nGenelkurmay Başkanı Silahlı Kuvvetlerin komutanıdır (II) ve savaşta Başkomutanlığı CB adına yürütür (III); ancak Milli Savunma Bakanınca değil, Cumhurbaşkanınca atanır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Üst kademe yöneticisi olarak Genelkurmay Başkanı doğrudan Cumhurbaşkanı kararı ile atanır.\n• B) I numaralı bilgi yanlış olduğundan elenir.\n• C) Bakan atama yetkisine sahip değildir, yürütmenin başı Cumhurbaşkanı atar.\n• E) Atama yetkisi Cumhurbaşkanında olduğu için üç öncül birden doğru değildir.",
