    "questionText": "1982 Anayasası'na göre, TBMM Genel Kurulunda görüşülmesi esnasında iki defa görüşülmesi zorunlu olan ve ivedilikle görüşülemeyen kanun teklifi aşağıdakilerden hangisidir?",
