    "explanation": "✅ DOĞRU CEVAP: C) Mahkemelerin kurulması, görev ve yetkileri\nAnayasa m. 142 gereğince mahkemelerin kuruluşu, görev ve yetkileri ile işleyişi ve yargılama usulleri münhasıran kanunla düzenlenir; CBK ile düzenlenemez.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Bakanlıkların kurulması, kaldırılması ve teşkilat yapısı Anayasa m. 106 uyarınca doğrudan CBK ile düzenlenir.\n• B) Üst kademe yöneticilerinin atanma usulleri Anayasa m. 104 uyarınca CBK ile belirlenir.\n• D) DDK'nın işleyişi, üyelerinin görev süresi ve özlük işleri anayasa gereği CBK ile düzenlenir.\n• E) MGK Genel Sekreterliğinin teşkilat yapısı Anayasa m. 118 uyarınca CBK ile düzenlenir.",
