    "questionText": "Kamu hizmeti ihtiyaç duyulduğunda kesintisiz yürütülen bir hizmettir. Emniyet teşkilatı günün her saatinde tatil günleri dâhil faaliyettedir; okullar ise tatil günlerinde kapalıdır. Bu durum kamu hizmetinin hangi ilkesinin bir sonucudur?",
