    "explanation": "✅ DOĞRU CEVAP: A) I ve II\nBarolar kamu kurumu niteliğinde meslek kuruluşudur; mahalle ise idari bir birim olup mahalli idare kuruluşu veya kamu tüzel kişiliği değildir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Çeşme Belediyesi anayasal bir mahalli idare kuruluşudur.\n• C) Belediyeler mahalli idarelerin temel unsurlarındandır.\n• D) Adıyaman İl Özel İdaresi Anayasa m. 127 kapsamında açıkça sayılan bir mahalli idaredir.\n• E) Belediye ve İl Özel İdaresi mahalli idare kuruluşu olduğundan yer almayanlar sadece I ve II'dir.",
