    "explanation": "✅ DOĞRU CEVAP: D) Karar organı il genel meclisidir.\nİl genel meclisi il genel idaresinin değil, yerinden yönetim kuruluşu olan İl Özel İdaresinin karar organıdır; il genel idaresinin organları vali, il idare şube başkanları ve il idare kuruludur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Vali, il genel idaresinin başı ve en yüksek mülki amiridir.\n• B) İl ve ilçelerin kurulması, kaldırılması, adlarının değiştirilmesi mutlaka kanunla yapılır.\n• C) İllerde valilere tanınan yetki genişliği il genel idaresinin anayasal yönetim ilkesidir.\n• E) İl idaresi Anayasa m. 126 uyarınca ancak kanun ile kurulup kaldırılabilir.",
