    "questionText": "657 sayılı Devlet Memurları Kanunu'na göre, 2025 yılında hiç izin kullanmayan 13 yıllık devlet memuru Duru, 2026 yılında birleştirerek toplam en fazla kaç gün yıllık izin kullanabilir?",
