    "explanation": "✅ DOĞRU CEVAP: D) Güvenlik hakkı\nDMK m. 18'de düzenlenen 'Güvenlik' hakkı, kanunda belirtilen açık haller dışında memurun görevine ve mali haklarına keyfi olarak dokunulamayacağını güvence altına alır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İzin hakkı, memurun yıllık, mazeret, sağlık ve aylıksız izin haklarını düzenler.\n• B) Kovuşturma ve yargılama hakkı, memurların görev suçlarında izin usulüne tabi olmasını ifade eder.\n• C) Çekilme hakkı, memurun yazılı başvuruda bulunarak görevinden istifa edebilmesidir.\n• E) Yetki genişliği bir memur hakkı değil, merkezden yönetimin il düzeyindeki vali yetkisidir.",
