    "questionText": "• Türk Einstein'ı olarak tanınmıştır.\n• 26 yaşında Yale Üniversitesi'nde profesör unvanı almıştır.\n• Kuantum mekaniği, kimya ve biyoloji alanlarında önemli teoriler geliştirmiştir.\n• \"Bye Bye Türkçe\" adlı eseriyle tanınmıştır.\nYukarıda özellikleri verilen bilim insanımız aşağıdakilerden hangisidir?",
