    "markedAnswer": "D",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Oktay Sinanoğlu\nÖncüllerde özellikleri verilen; kuantum kimyası ve moleküler biyoloji alanında geliştirdiği matematiksel teorilerle 26 yaşında Yale Üniversitesi'nin son 300 yılındaki en genç tam profesörü olan, iki kez Nobel'e aday gösterilen, **\"Türk Einstein'ı\"** lakabıyla anılan ve Türkçenin korunmasına adadığı **\"Bye Bye Türkçe\"** kitabıyla tanınan bilim insanımız **OKTAY SİNANOĞLU**'dur (1935 - 2015).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Aziz Sancar: DNA onarımı ve sirkadiyen saat çalışmalarıyla 2015 Nobel Kimya Ödülü'nü kazanan Mardinli bilim insanımızdır.\n• C) Cahit Arf: \"Arf Değişmezi / Halkaları\" teoremini bulan ve 10 TL banknotumuzun arka yüzünde yer alan matematik dehamızdır.\n• D) Gazi Yaşargil: Mikronörocerrahinin kurucusu, Amerikan Beyin Cerrahları Birliği tarafından \"Yüzyılın Beyin Cerrahı\" seçilen tıp insanımızdır.\n• E) Fuat Sezgin: İslam Bilim ve Teknoloji Tarihi alanında dünyanın en büyük otoritesi kabul edilen ve 2019 yılı anısına ilan edilen bilim tarihçimizdir.\n\n💡 KPSS HAFIZA KARTI:\nÖSYM'nin En Çok Sorduğu Türk Bilim İnsanları:\n• **Oktay Sinanoğlu:** Türk Einstein'ı, Bye Bye Türkçe, Yale'de 26 yaşında profesör.\n• **Aziz Sancar:** 2015 Nobel Kimya Ödülü (DNA Onarımı).\n• **Cahit Arf:** Arf Teoremi (10 Türk Lirası).\n• **Gazi Yaşargil:** Yüzyılın Beyin Cerrahı.\n• **Fuat Sezgin:** İslam Bilim Tarihi Müzesi kurucusu.",
    "isMapQuestion": false,
