    "questionText": "Türkiye’nin ev sahipliğinde gerçekleştirilen ilk uluslararası çok sporlu organizasyon olan 1971 Akdeniz Oyunları aşağıdaki şehirlerimizden hangisinde düzenlenmiştir?",
    "options": {
      "A": "İstanbul",
      "B": "Ankara",
      "C": "Antalya",
      "D": "Mersin",
      "E": "İzmir"
    },
    "markedAnswer": "C",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) İzmir\nTürkiye Cumhuriyeti tarihinde ev sahipliği yapılan **İLK ULUSLARARASI ÇOK SPORLU ORGANİZASYON, 1971 YILINDA İZMİR'DE DÜZENLENEN 6. AKDENİZ OYUNLARI**dır. Bu dev oyunlar için İzmir'de tarihi Atatürk Stadyumu, Halkapınar Spor Salonu ve Alsancak spor tesisleri inşa edilmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İstanbul: Türkiye'nin spor başkenti olmakla birlikte Akdeniz Oyunları'na ev sahipliği yapmamıştır (Şampiyonlar Ligi, Formula 1 vb. tekil organizasyonlar düzenlenmiştir).\n• B) Ankara: Akdeniz Oyunları düzenlenmemiştir.\n• C) Antalya: Akdeniz Oyunları düzenlenmemiştir.\n• D) Mersin: Mersin 2013 yılında 17. Akdeniz Oyunları'na ev sahipliği yapmıştır (Türkiye'nin 2. ev sahipliğidir; ilk organizasyon 1971'de İzmir'dedir).\n\n💡 KPSS HAFIZA KARTI:\nTürkiye'deki Büyük Uluslararası Spor Organizasyonları:\n• **1971 Akdeniz Oyunları (İLKİ)** -> **İZMİR**\n• **2013 Akdeniz Oyunları** -> **MERSİN**\n• **2011 Kış Üniversiade** -> **ERZURUM**\n• **2017 İşitme Engelliler Olimpiyatı (Deaflympics)** -> **SAMSUN**\n• **2021 İslami Dayanışma Oyunları** -> **KONYA**",
