    "explanation": "✅ DOĞRU CEVAP: B) John Locke\nJohn Locke, zihnin doğuştan boş bir levha (tabula rasa) olduğunu ve tüm bilgilerin sonradan deneyimlerle kazanıldığını savunmuştur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Denis Diderot, Fransız Aydınlanması'nın en önemli simalarından olup ünlü Ansiklopedi (Encyclopédie) projesinin baş editörüdür.\n• C) Montesquieu, Kanunların Ruhu adlı eserinde kuvvetler ayrılığı prensibini geliştiren düşünürdür.\n• D) Jean-Jacques Rousseau, Toplum Sözleşmesi teorisi ile doğrudan halk egemenliğini savunan Fransız filozoftur.\n• E) Voltaire, Aydınlanma döneminde din ve vicdan hürriyetinin ateşli savunucusu olan yazardır.",
