    "explanation": "✅ DOĞRU CEVAP: A) İlahi Komedya\nDante'nin Cehennem, Araf ve Cennet'e yaptığı manevi yolculuğu anlatan La Divina Commedia eseri Rönesans'ın müjdecisidir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Decameron, Giovanni Boccaccio'nun veba salgınını anlatan 100 hikâyelik eseridir.\n• C) Don Kişot, Miguel de Cervantes'in modern romanın başlangıcı sayılan şövalye parodisidir.\n• D) Faust, Johann Wolfgang von Goethe'nin ruhunu şeytana satan bilgini anlattığı dramatik tragedyasıdır.\n• E) Kayıp Cennet, John Milton'ın insanın cennetten kovuluşunu anlattığı epik şiiridir.",
