    "explanation": "✅ DOĞRU CEVAP: A) Honoré de Balzac\nHonoré de Balzac, 19. yüzyıl Fransız toplumunu tüm sınıflarıyla yansıttığı İnsanlık Komedyası (La Comédie humaine) derlemesi ve Goriot Baba romanının yazarıdır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Gustave Flaubert, Madame Bovary ve Salambo romanlarının yazarıdır.\n• C) Émile Zola, natüralizmin kurucusu olup Germinal ve Nana romanlarının yazarıdır.\n• D) Victor Hugo, Fransız Romantizminin lideri, Sefiller ve Notre Dame'ın Kamburu'nun yazarıdır.\n• E) Stendhal, Kırmızı ve Siyah ile Parma Manastırı romanlarının yazarıdır.",
