    "topic": "Uluslararası Örgütler / TÜRKSOY",
    "questionText": "1993 yılında Azerbaycan, Kazakistan, Kırgızistan, Özbekistan, Türkmenistan ve Türkiye tarafından merkezi Ankara olarak kurulan uluslararası kültür teşkilatı hangisidir?",
    "options": {
      "A": "TÜRKSOY (Uluslararası Türk Kültürü Teşkilatı)",
      "B": "Türk Devletleri Teşkilatı",
      "C": "Petrol İhraç Eden Ülkeler Birliği (OPEC)",
      "D": "Karadeniz Ekonomik İşbirliği Örgütü (KEİ)",
      "E": "D-8 Ekonomik İşbirliği Örgütü"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) TÜRKSOY (Uluslararası Türk Kültürü Teşkilatı)\nTÜRKSOY, 1993'te Almatı Anlaşması ile Türk dili konuşan ülkeler arasında kültürel bağları güçlendirmek üzere Ankara merkezli kurulmuştur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Türk Devletleri Teşkilatı, 2009 Nahçıvan Anlaşması ile siyasi ve ekonomik çatı örgüt olarak kurulmuştur.\n• C) OPEC, 1960'ta Bağdat'ta kurulan petrol ihraç eden ülkeler birliğidir.\n• D) KEİ, 1992'de İstanbul'da kurulan Karadeniz havzası ekonomik işbirliği örgütüdür.\n• E) D-8, 1997'de gelişmekte olan sekiz İslam ülkesinin ekonomik işbirliği için kurulmuştur.",
