    "explanation": "✅ DOĞRU CEVAP: C) Yaşar Erkan\nYaşar Erkan, 1936 Berlin Olimpiyatları'nda 61 kg grekoromende şampiyon olarak Türkiye'ye tarihindeki ilk olimpiyat altın madalyasını kazandırmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Gazanfer Bilge, 1948 Londra Olimpiyatları'nda serbest güreşte altın madalya kazanmıştır.\n• B) Celal Atik, 1948 Londra Olimpiyatları şampiyonu efsane güreşçimizdir.\n• D) Hamit Kaplan, 1956 Melbourne Olimpiyatları'nda ağır sıklette altın madalya almıştır.\n• E) Nasuh Akar, 1948 Londra Olimpiyatları'nda serbest stilde altın madalya kazanan güreşçimizdir.",
