    "explanation": "✅ DOĞRU CEVAP: C) Alexander Graham Bell\nAlexander Graham Bell, 1876 yılında patentini aldığı telefon ile elektrikli ses iletimini başlatmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Thomas Edison, akkor ampul, fonograf ve film kamerasını icat eden Amerikalı mucittir.\n• B) Guglielmo Marconi, kablosuz telgraf ve radyo dalgalarıyla haberleşmenin öncüsüdür.\n• D) Samuel Morse, elektrikli telgrafı ve Mors alfabesini geliştiren mucittir.\n• E) Heinrich Hertz, elektromanyetik radyo dalgalarının varlığını deneysel olarak kanıtlayan fizikçidir.",
