    "questionText": "\"Zamanın Kısa Tarihi\" ve \"Büyük Tasarım\" kitaplarıyla tanınan, kara deliklerin ışıma yaydığını (Hawking ışıması) ispatlayan İngiliz teorik fizikçi kimdir?",
