    "explanation": "✅ DOĞRU CEVAP: A) Câbir bin Hayyân\nCâbir bin Hayyân (Geber), imbik düzeneğini geliştiren, mineral asitleri keşfeden ve simyayı deneysel kimyaya dönüştüren öncüdür.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) İbn-i Heysem (Alhazen), Kitâbü'l-Menâzır eseriyle modern optik biliminin kurucusudur.\n• C) el-Hârizmî, cebir biliminin kurucusu ve sıfır (0) rakamını matematiğe kazandıran bilgindir.\n• D) İbn-i Sînâ (Avicenna), El-Kanun fi't-Tıbb eseriyle tanınan hekim ve filozoftur.\n• E) Bîrûnî, Dünya'nın yarıçapını ve dönüşünü hesaplayan büyük astronom ve coğrafyacıdır.",
